cat > /workspace/processor.go << 'GOEOF'
package main

import (
	"bufio"
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"
)

// FileResult holds the count results for a single file
type FileResult struct {
	Language   string
	Filename   string
	Lines      int64
	Code       int64
	Comments   int64
	Blanks     int64
	Complexity int64
	Bytes      int64
	// For ULOC
	LineHashes map[string]bool
	// For character stats
	MaxLine    int
	SumLine    int64
}

// isBinaryFile checks if a file appears to be binary
func isBinaryFile(data []byte) bool {
	limit := len(data)
	if limit > 8000 {
		limit = 8000
	}
	for i := 0; i < limit; i++ {
		if data[i] == 0 {
			return true
		}
	}
	return false
}

// isValidUTF8 checks if data is valid UTF-8
func isValidUTF8(data []byte) bool {
	return utf8.Valid(data)
}

// ProcessFile counts lines in a file given the language definition
func ProcessFile(filename string, lang *LanguageDef, opts *Options) (*FileResult, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}

	result := &FileResult{
		Language: lang.Name,
		Filename: filename,
		Bytes:    int64(len(data)),
	}

	if opts.TrackULOC {
		result.LineHashes = make(map[string]bool)
	}

	// Check if binary (unless disabled)
	if !opts.DisableBinaryCheck && isBinaryFile(data) {
		return nil, nil
	}

	countLines(data, lang, result, opts)
	return result, nil
}

// countLines does the actual line counting
func countLines(data []byte, lang *LanguageDef, result *FileResult, opts *Options) {
	scanner := bufio.NewScanner(bytes.NewReader(data))

	// State
	inMultiLineComment := false
	multiLineEnd := ""
	multiLineStart := "" // track which multiline start we used

	_ = multiLineStart

	for scanner.Scan() {
		line := scanner.Text()
		result.Lines++

		trimmed := strings.TrimSpace(line)

		if opts.TrackCharacter {
			lineLen := len(line)
			if lineLen > result.MaxLine {
				result.MaxLine = lineLen
			}
			result.SumLine += int64(lineLen)
		}

		if trimmed == "" {
			result.Blanks++
			if inMultiLineComment {
				result.Comments++
				result.Blanks-- // blank lines inside multiline comment are counted as comment
			}
			continue
		}

		// Handle multi-line comment state
		if inMultiLineComment {
			// Check for end of multi-line comment
			endIdx := strings.Index(trimmed, multiLineEnd)
			if endIdx >= 0 {
				inMultiLineComment = false
				// Check if there's code after the end
				afterEnd := strings.TrimSpace(trimmed[endIdx+len(multiLineEnd):])
				if afterEnd != "" {
					// Has code after comment end
					result.Code++
					if opts.CalcComplexity {
						result.Complexity += countComplexity(afterEnd, lang.ComplexityChecks)
					}
				} else {
					result.Comments++
				}
			} else {
				result.Comments++
			}

			if opts.TrackULOC {
				result.LineHashes[trimmed] = true
			}
			continue
		}

		// Check for multi-line comment start
		foundMultiLine := false
		if len(lang.MultiLineComment) > 0 {
			for _, pair := range lang.MultiLineComment {
				if len(pair) < 2 {
					continue
				}
				start := pair[0]
				end := pair[1]

				idx := strings.Index(trimmed, start)
				if idx >= 0 {
					// Check there's no line comment before it
					lineCommentBefore := false
					for _, lc := range lang.LineComment {
						lcIdx := strings.Index(trimmed, lc)
						if lcIdx >= 0 && lcIdx < idx {
							lineCommentBefore = true
							break
						}
					}
					if lineCommentBefore {
						break
					}

					// Check if end is on same line
					searchFrom := idx + len(start)
					endIdx := strings.Index(trimmed[searchFrom:], end)
					if endIdx >= 0 {
						// Inline comment - check if there's real code before it
						beforeComment := strings.TrimSpace(trimmed[:idx])
						afterComment := strings.TrimSpace(trimmed[searchFrom+endIdx+len(end):])
						if beforeComment != "" || afterComment != "" {
							result.Code++
							if opts.CalcComplexity {
								result.Complexity += countComplexity(beforeComment+" "+afterComment, lang.ComplexityChecks)
							}
						} else {
							result.Comments++
						}
					} else {
						// Start of multi-line comment
						inMultiLineComment = true
						multiLineEnd = end
						multiLineStart = start
						beforeComment := strings.TrimSpace(trimmed[:idx])
						if beforeComment != "" {
							result.Code++
							if opts.CalcComplexity {
								result.Complexity += countComplexity(beforeComment, lang.ComplexityChecks)
							}
						} else {
							result.Comments++
						}
					}
					foundMultiLine = true
					break
				}
			}
		}

		if foundMultiLine {
			if opts.TrackULOC {
				result.LineHashes[trimmed] = true
			}
			continue
		}

		// Check for line comment
		isComment := false
		for _, lc := range lang.LineComment {
			if strings.HasPrefix(trimmed, lc) {
				isComment = true
				break
			}
		}

		if isComment {
			result.Comments++
		} else {
			result.Code++
			if opts.CalcComplexity {
				result.Complexity += countComplexity(trimmed, lang.ComplexityChecks)
			}
		}

		if opts.TrackULOC {
			result.LineHashes[trimmed] = true
		}
	}
}

// countComplexity counts complexity keywords in a line
func countComplexity(line string, checks []string) int64 {
	var count int64
	for _, check := range checks {
		// Look for the keyword as a word boundary
		idx := 0
		for {
			pos := strings.Index(line[idx:], check)
			if pos < 0 {
				break
			}
			absPos := idx + pos
			// Check word boundaries
			before := absPos == 0 || !isAlphaNum(rune(line[absPos-1]))
			after := absPos+len(check) >= len(line) || !isAlphaNum(rune(line[absPos+len(check)]))
			if before && after {
				count++
			}
			idx = absPos + 1
			if idx >= len(line) {
				break
			}
		}
	}
	return count
}

func isAlphaNum(r rune) bool {
	return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_'
}

// DetectLanguage determines the language for a file
func DetectLanguage(filename string, content []byte) *LanguageDef {
	base := filepath.Base(filename)
	lower := strings.ToLower(base)

	// First try exact filename match (for files like Makefile, Dockerfile)
	for i := range Languages {
