// FileResult holds the count results for a single file
type FileResult struct {
	Language   string
	Filename   string
	Lines      int64
	Code       int64
	Comments   int64
	Blanks     int64
	Complexity int64
	Bytes      int64
	// For ULOC
	LineHashes map[string]bool
	// For character stats
	MaxLine int
	SumLine int64
}

// isBinaryFile checks if a file appears to be binary
func isBinaryFile(data []byte) bool {
	limit := len(data)
	if limit > 8000 {
		limit = 8000
	}
	for i := 0; i < limit; i++ {
		if data[i] == 0 {
			return true
		}
	}
	return false
}

// ProcessFile counts lines in a file given the language definition
func ProcessFile(filename string, lang *LanguageDef, opts *Options) (*FileResult, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}

	result := &FileResult{
		Language: lang.Name,
		Filename: filename,
		Bytes:    int64(len(data)),
	}

	if opts.TrackULOC {
		result.LineHashes = make(map[string]bool)
	}

	// Check if binary (unless disabled)
	if !opts.DisableBinaryCheck && isBinaryFile(data) {
		return nil, nil
	}

	if !utf8.Valid(data) {
		// Try to process as latin-1 still
	}

	countLines(data, lang, result, opts)
	return result, nil
}

type parseState int

const (
	stateCode    parseState = iota
	stateComment parseState = iota
)

// countLines does the actual line counting
func countLines(data []byte, lang *LanguageDef, result *FileResult, opts *Options) {
	scanner := bufio.NewScanner(bytes.NewReader(data))
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)

	inMultiLineComment := false
	multiLineEnd := ""

	for scanner.Scan() {
		line := scanner.Text()
		result.Lines++

		trimmed := strings.TrimSpace(line)

		if opts.TrackCharacter {
			lineLen := len(line)
			if lineLen > result.MaxLine {
				result.MaxLine = lineLen
			}
			result.SumLine += int64(lineLen)
		}

		if opts.TrackULOC && trimmed != "" {
			result.LineHashes[trimmed] = true
		}

		if trimmed == "" {
			if inMultiLineComment {
				result.Comments++
			} else {
				result.Blanks++
			}
			continue
		}

		if inMultiLineComment {
			endIdx := strings.Index(trimmed, multiLineEnd)
			if endIdx >= 0 {
				inMultiLineComment = false
				afterEnd := strings.TrimSpace(trimmed[endIdx+len(multiLineEnd):])
				if afterEnd != "" && !isLineComment(afterEnd, lang.LineComment) {
					result.Code++
					if opts.CalcComplexity {
						result.Complexity += countComplexity(afterEnd, lang.ComplexityChecks)
					}
				} else if afterEnd != "" {
					result.Comments++
				} else {
					result.Comments++
				}
			} else {
				result.Comments++
			}
			continue
		}

		// Not in multi-line comment
		// First check if line starts with a line comment
		if isLineComment(trimmed, lang.LineComment) {
			result.Comments++
			continue
		}

		// Look for multi-line comment start
		mlCommentFound := false
		if len(lang.MultiLineComment) > 0 {
			for _, pair := range lang.MultiLineComment {
				if len(pair) < 2 {
					continue
				}
				mlStart := pair[0]
				mlEnd := pair[1]

				idx := findCommentStart(trimmed, mlStart, lang.LineComment)
				if idx < 0 {
					continue
				}

				// Found multi-line comment start
				beforeComment := strings.TrimSpace(trimmed[:idx])
				rest := trimmed[idx+len(mlStart):]

				// Check if end is on same line
				endIdx := strings.Index(rest, mlEnd)
				if endIdx >= 0 {
					afterComment := strings.TrimSpace(rest[endIdx+len(mlEnd):])
					// Inline block comment
					if beforeComment != "" {
						result.Code++
						if opts.CalcComplexity {
							result.Complexity += countComplexity(beforeComment, lang.ComplexityChecks)
						}
					} else if afterComment != "" {
						// Comment followed by code - count as code
						result.Code++
						if opts.CalcComplexity {
							result.Complexity += countComplexity(afterComment, lang.ComplexityChecks)
						}
					} else {
						result.Comments++
					}
				} else {
					// Multi-line comment starts here
					inMultiLineComment = true
					multiLineEnd = mlEnd
					if beforeComment != "" {
						result.Code++
						if opts.CalcComplexity {
							result.Complexity += countComplexity(beforeComment, lang.ComplexityChecks)
						}
					} else {
						result.Comments++
					}
				}
				mlCommentFound = true
				break
			}
		}

		if !mlCommentFound {
			result.Code++
			if opts.CalcComplexity {
				result.Complexity += countComplexity(trimmed, lang.ComplexityChecks)
			}
		}
	}
}

func isLineComment(line string, lineComments []string) bool {
	for _, lc := range lineComments {
		if strings.HasPrefix(line, lc) {
			return true
		}
	}
	return false
}

// findCommentStart finds the position of mlStart in line, ensuring no line comment comes first
func findCommentStart(line, mlStart string, lineComments []string) int {
	idx := strings.Index(line, mlStart)
	if idx < 0 {
		return -1
	}
	// Check no line comment is before mlStart
	for _, lc := range lineComments {
		lcIdx := strings.Index(line, lc)
		if lcIdx >= 0 && lcIdx < idx {
			return -1
		}
	}
	return idx
}

// countComplexity counts complexity keywords in a line
func countComplexity(line string, checks []string) int64 {
	var count int64
	for _, check := range checks {
		idx := 0
		for idx < len(line) {
			pos := strings.Index(line[idx:], check)
			if pos < 0 {
				break
			}
			absPos := idx + pos
			before := absPos == 0 || !isWordChar(rune(line[absPos-1]))
			end := absPos + len(check)
			after := end >= len(line) || !isWordChar(rune(line[end]))
			if before && after {
				count++
			}
			idx = absPos + 1
		}
	}
	return count
}

func isWordChar(r rune) bool {
	return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_'
}

// DetectLanguage determines the language for a file
func DetectLanguage(filename string, content []byte) *LanguageDef {
	base := filepath.Base(filename)
	lower := strings.ToLower(base)

	// Check for dot-leading files and exact name matches (case-insensitive)
	for i := range Languages {
		for _, ext := range Languages[i].Extensions {
			if lower == strings.ToLower(ext) {
				return &Languages[i]
			}
		}
	}

	// Handle compound extensions like .blade.php, .d.ts, .tf.json
	parts := strings.Split(lower, ".")
	if len(parts) > 2 {
		compound := strings.Join(parts[1:], ".") // everything after first dot
		for i := range Languages {
			for _, langExt := range Languages[i].Extensions {
				if langExt == compound {
					return &Languages[i]
				}
			}
		}
		// Two-part compound
		compound2 := parts[len(parts)-2] + "." + parts[len(parts)-1]
		for i := range Languages {
			for _, langExt := range Languages[i].Extensions {
				if langExt == compound2 {
					return &Languages[i]
				}
			}
		}
	}

	// Simple extension match
	var ext string
	if idx := strings.LastIndex(lower, "."); idx >= 0 {
		ext = lower[idx+1:]
	}

	if ext != "" {
		for i := range Languages {
			for _, langExt := range Languages[i].Extensions {
				if langExt == ext {
					return &Languages[i]
				}
			}
		}
	}

	// Try shebang detection
	if len(content) >= 2 && content[0] == '#' && content[1] == '!' {
		shebang := ""
		for i := 2; i < len(content) && i < 200; i++ {
			if content[i] == '\n' || content[i] == '\r' {
				break
			}
			shebang += string(content[i])
		}
		return detectShebang(shebang)
	}

	return nil
}

func detectShebang(shebang string) *LanguageDef {
	shebang = strings.TrimSpace(shebang)
	interp := shebang
	if idx := strings.LastIndex(shebang, "/"); idx >= 0 {
		interp = shebang[idx+1:]
	}
	// Handle "env python3" etc
	if strings.HasPrefix(interp, "env ") {
		interp = strings.TrimPrefix(interp, "env ")
		if idx := strings.Index(interp, " "); idx >= 0 {
			interp = interp[:idx]
		}
	}
	// Remove version suffix for matching
	interpBase := interp
	for i, c := range interp {
		if c >= '0' && c <= '9' || c == '.' {
			interpBase = interp[:i]
			break
		}
	}

	interpMap := map[string]string{
		"python":  "Python",
		"ruby":    "Ruby",
		"perl":    "Perl",
		"perl6":   "Raku",
		"node":    "JavaScript",
		"nodejs":  "JavaScript",
		"bash":    "BASH",
		"sh":      "Shell",
		"zsh":     "Zsh",
		"fish":    "Fish",
		"csh":     "C Shell",
		"tcsh":    "C Shell",
		"ksh":     "Korn Shell",
		"awk":     "AWK",
		"lua":     "Lua",
		"tclsh":   "TCL",
		"wish":    "TCL",
		"Rscript": "R",
		"julia":   "Julia",
		"php":     "PHP",
		"groovy":  "Groovy",
		"scala":   "Scala",
		"expect":  "Expect",
		"crystal": "Crystal",
		"elixir":  "Elixir",
		"nu":      "Nushell",
	}

	candidates := []string{interp, interpBase}
	for _, c := range candidates {
		if langName, ok := interpMap[c]; ok {
			for i := range Languages {
				if Languages[i].Name == langName {
					return &Languages[i]
				}
			}
		}
	}
	return nil
}

// IgnorePattern represents an entry from .gitignore/.ignore
type IgnorePattern struct {
	Pattern string
	IsDir   bool
	Negate  bool
	Base    string // base directory of the ignore file
}

func LoadIgnorePatterns(dir string, opts *Options) []IgnorePattern {
	var patterns []IgnorePattern
	if !opts.NoIgnore {
		patterns = append(patterns, loadIgnoreFile(filepath.Join(dir, ".ignore"), dir)...)
	}
	if !opts.NoGitIgnore {
		patterns = append(patterns, loadIgnoreFile(filepath.Join(dir, ".gitignore"), dir)...)
	}
	if !opts.NoSCCIgnore {
		patterns = append(patterns, loadIgnoreFile(filepath.Join(dir, ".sccignore"), dir)...)
	}
	return patterns
}

func LoadIgnorePatternsFromDir(dir string, opts *Options) []IgnorePattern {
	return LoadIgnorePatterns(dir, opts)
}

func loadIgnoreFile(path, base string) []IgnorePattern {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var patterns []IgnorePattern
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}
		isDir := strings.HasSuffix(line, "/")
		if isDir {
			line = line[:len(line)-1]
		}
		patterns = append(patterns, IgnorePattern{
			Pattern: line,
			IsDir:   isDir,
			Negate:  negate,
			Base:    base,
		})
	}
	return patterns
}

func isIgnored(relPath, name string, isDir bool, patterns []IgnorePattern) bool {
	for _, p := range patterns {
		if p.IsDir && !isDir {
			continue
		}
		matched := matchIgnorePattern(relPath, name, p.Pattern)
		if matched {
			if p.Negate {
				return false
			}
			return true
		}
	}
	return false
}

func matchIgnorePattern(relPath, name, pattern string) bool {
	// Try exact name match
	if matched, err := filepath.Match(pattern, name); err == nil && matched {
		return true
	}
	// Try full path match
	if matched, err := filepath.Match(pattern, relPath); err == nil && matched {
		return true
	}
	// Try with ** (simplified)
	if strings.Contains(pattern, "**") {
		re := globToRegex(pattern)
		if re != nil && re.MatchString(relPath) {
			return true
		}
	}
	return false
}

func globToRegex(pattern string) *regexp.Regexp {
	// Convert glob pattern to regex
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		switch c {
		case '*':
			if i+1 < len(pattern) && pattern[i+1] == '*' {
				sb.WriteString(".*")
				i++
			} else {
				sb.WriteString("[^/]*")
			}
		case '?':
			sb.WriteString("[^/]")
		case '.', '+', '(', ')', '{', '}', '[', ']', '^', '$', '|', '\\':
			sb.WriteByte('\\')
			sb.WriteByte(c)
		default:
			sb.WriteByte(c)
		}
	}
	sb.WriteString("$")
	re, err := regexp.Compile(sb.String())
	if err != nil {
		return nil
	}
	return re
}

// WalkDirectory walks a directory and returns all files to process
func WalkDirectory(paths []string, opts *Options) ([]string, error) {
	var allFiles []string

	for _, path := range paths {
		info, err := os.Stat(path)
		if err != nil {
			return nil, err
		}
		if info.IsDir() {
			ignorePatterns := LoadIgnorePatterns(path, opts)
			var files []string
			err = walkDir(path, path, opts, ignorePatterns, &files)
			if err != nil {
				return nil, err
			}
			allFiles = append(allFiles, files...)
		} else {
			allFiles = append(allFiles, path)
		}
	}
	return allFiles, nil
}

func walkDir(root, dir string, opts *Options, ignorePatterns []IgnorePattern, files *[]string) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}

	for _, entry := range entries {
		name := entry.Name()
		fullPath := filepath.Join(dir, name)
		relPath, _ := filepath.Rel(root, fullPath)

		if entry.IsDir() {
			excluded := false
			for _, excl := range opts.ExcludeDir {
				if name == excl {
					excluded = true
					break
				}
			}
			if excluded {
				continue
			}

			if matchesNotMatch(relPath, opts.NotMatch) {
				continue
			}

			if isIgnored(relPath, name, true, ignorePatterns) {
				continue
			}

			subIgnore := make([]IgnorePattern, len(ignorePatterns))
			copy(subIgnore, ignorePatterns)
			subIgnore = append(subIgnore, LoadIgnorePatternsFromDir(fullPath, opts)...)
			if err := walkDir(root, fullPath, opts, subIgnore, files); err != nil {
				return err
			}
			continue
		}

		if !opts.IncludeSymlinks && entry.Type()&os.ModeSymlink != 0 {
			continue
		}

		if matchesNotMatch(relPath, opts.NotMatch) {
			continue
		}

		if isIgnored(relPath, name, false, ignorePatterns) {
			continue
		}

		if isExcludedFile(name, opts) {
			continue
		}

		*files = append(*files, fullPath)
	}

	return nil
}

func isExcludedFile(name string, opts *Options) bool {
	lower := strings.ToLower(name)
	for _, excl := range opts.ExcludeFile {
		if lower == strings.ToLower(excl) || name == excl {
			return true
		}
	}
	return false
}

func matchesNotMatch(path string, patterns []string) bool {
	if len(patterns) == 0 {
		return false
	}
	for _, p := range patterns {
		re, err := regexp.Compile(p)
		if err == nil {
			if re.MatchString(path) || re.MatchString(filepath.Base(path)) {
				return true
			}
		}
	}
	return false
}
