// IgnorePattern represents an entry from .gitignore/.ignore
type IgnorePattern struct {
	Pattern string
	IsDir   bool
	Negate  bool
	Base    string // base directory of the ignore file
}

func LoadIgnorePatterns(dir string, opts *Options) []IgnorePattern {
	var patterns []IgnorePattern
	if !opts.NoIgnore {
		patterns = append(patterns, loadIgnoreFile(filepath.Join(dir, ".ignore"), dir)...)
	}
	if !opts.NoGitIgnore {
		patterns = append(patterns, loadIgnoreFile(filepath.Join(dir, ".gitignore"), dir)...)
	}
	if !opts.NoSCCIgnore {
		patterns = append(patterns, loadIgnoreFile(filepath.Join(dir, ".sccignore"), dir)...)
	}
	return patterns
}

func LoadIgnorePatternsFromDir(dir string, opts *Options) []IgnorePattern {
	return LoadIgnorePatterns(dir, opts)
}

func loadIgnoreFile(path, base string) []IgnorePattern {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var patterns []IgnorePattern
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}
		isDir := strings.HasSuffix(line, "/")
		if isDir {
			line = line[:len(line)-1]
		}
		patterns = append(patterns, IgnorePattern{
			Pattern: line,
			IsDir:   isDir,
			Negate:  negate,
			Base:    base,
		})
	}
	return patterns
