// findCommentStart finds the position of mlStart in line, ensuring no line comment comes first
func findCommentStart(line, mlStart string, lineComments []string) int {
	idx := strings.Index(line, mlStart)
	if idx < 0 {
		return -1
	}
	// Check no line comment is before mlStart
	for _, lc := range lineComments {
		lcIdx := strings.Index(line, lc)
		if lcIdx >= 0 && lcIdx < idx {
			return -1
		}
	}
	return idx
}

// countComplexity counts complexity keywords in a line
func countComplexity(line string, checks []string) int64 {
	var count int64
	for _, check := range checks {
		idx := 0
		for idx < len(line) {
			pos := strings.Index(line[idx:], check)
			if pos < 0 {
