		}

		if matchesNotMatch(relPath, opts.NotMatch) {
			continue
		}

		if isIgnored(relPath, name, false, ignorePatterns) {
			continue
		}

		if isExcludedFile(name, opts) {
			continue
		}

		*files = append(*files, fullPath)
	}

	return nil
}

func isExcludedFile(name string, opts *Options) bool {
	lower := strings.ToLower(name)
	for _, excl := range opts.ExcludeFile {
		if lower == strings.ToLower(excl) || name == excl {
			return true
		}
