// CalcCocomo calculates the COCOMO estimate
func CalcCocomo(codeLinesTotal int64, opts *Options) CocomoResult {
	pt := opts.CocomoProjectType
	if pt == "" {
		pt = "organic"
	}

	var params CocomoProjectType
	var isCustom bool

	if cp, ok := cocomoTypes[pt]; ok {
		params = cp
	} else if len(pt) > 7 && pt[:7] == "custom," {
		// Parse custom type
		var a, b, c, d float64
		n, _ := scanFloat4(pt[7:], &a, &b, &c, &d)
		if n == 4 {
			params = CocomoProjectType{Name: "custom", A: a, B: b, C: c, D: d}
			isCustom = true
		} else {
			params = cocomoTypes["organic"]
		}
	} else {
		params = cocomoTypes["organic"]
	}

	_ = isCustom

	kloc := float64(codeLinesTotal) / 1000.0
	effort := params.A * math.Pow(kloc, params.B) * opts.EAF
	timeMonths := params.C * math.Pow(effort, params.D)
	people := effort / timeMonths

	salary := float64(opts.AvgWage)
	if salary == 0 {
		salary = 56286
	}
	overhead := opts.Overhead
	if overhead == 0 {
		overhead = 2.4
	}

	cost := effort * salary / 12.0 * overhead

	return CocomoResult{
		ProjectType:    params.Name,
		EstimatedCost:  cost,
		ScheduleMonths: timeMonths,
		PeopleRequired: people,
	}
}

func scanFloat4(s string, a, b, c, d *float64) (int, error) {
	// Parse "1.0,1.0,1.0,1.0"
	parts := splitBy(s, ',')
	if len(parts) < 4 {
		return 0, nil
	}
	var err error
	*a, err = parseFloat(parts[0])
	if err != nil {
		return 0, err
	}
	*b, err = parseFloat(parts[1])
	if err != nil {
		return 1, err
	}
	*c, err = parseFloat(parts[2])
	if err != nil {
		return 2, err
	}
	*d, err = parseFloat(parts[3])
	if err != nil {
		return 3, err
	}
	return 4, nil
}

func splitBy(s string, sep rune) []string {
	var result []string
	current := ""
	for _, c := range s {
		if c == sep {
			result = append(result, current)
			current = ""
		} else {
			current += string(c)
		}
	}
	result = append(result, current)
	return result
}

func parseFloat(s string) (float64, error) {
	var result float64
	_, err := fmt.Sscanf(s, "%f", &result)
	return result, err
}
