	"strings"
	"time"
)

// LanguageSummary holds aggregated stats for a language
type LanguageSummary struct {
	Name              string
	Bytes             int64
	CodeBytes         int64
	Lines             int64
	Code              int64
	Comment           int64
	Blank             int64
	Complexity        int64
	Count             int64
	WeightedComplexity float64
	Files             []*FileResult
	LineLength        *LineLengthSummary
	ULOC              int64
}

type LineLengthSummary struct {
	Max  int
	Mean float64
}

// FormatOutput writes the output in the requested format
func FormatOutput(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	switch opts.Format {
	case "json":
		formatJSON(summaries, w)
	case "json2":
		formatJSON2(summaries, opts, totalBytes, elapsed, w)
	case "csv":
		formatCSV(summaries, w)
	case "csv-stream":
		formatCSV(summaries, w)
	case "cloc-yaml":
		formatClocYAML(summaries, opts, totalBytes, elapsed, w)
	case "html":
		formatHTML(summaries, opts, w)
	case "html-table":
		formatHTMLTable(summaries, opts, w)
	case "sql":
		formatSQL(summaries, opts, w)
	case "sql-insert":
		formatSQLInsert(summaries, opts, w)
	case "openmetrics":
		formatOpenMetrics(summaries, w)
	default:
		formatTabular(summaries, opts, totalBytes, elapsed, w)
	}
}

func formatJSON(summaries []*LanguageSummary, w io.Writer) {
	// Sanitize for JSON
	for _, s := range summaries {
		if s.Files == nil {
			s.Files = []*FileResult{}
		}
	}
	data, _ := json.Marshal(summaries)
	fmt.Fprintf(w, "%s", data)
}

func formatJSON2(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	cocomo := CalcCocomo(totalCodeLines(summaries), opts)
	type json2Output struct {
		LanguageSummary       []*LanguageSummary `json:"languageSummary"`
		EstimatedCost         float64            `json:"estimatedCost"`
		EstimatedScheduleMonths float64          `json:"estimatedScheduleMonths"`
		EstimatedPeople       float64            `json:"estimatedPeople"`
	}
	out := json2Output{
		LanguageSummary:       summaries,
		EstimatedCost:         cocomo.EstimatedCost,
		EstimatedScheduleMonths: cocomo.ScheduleMonths,
		EstimatedPeople:       cocomo.PeopleRequired,
	}
	for _, s := range summaries {
		if s.Files == nil {
			s.Files = []*FileResult{}
		}
	}
	data, _ := json.Marshal(out)
	fmt.Fprintf(w, "%s", data)
}

func formatCSV(summaries []*LanguageSummary, w io.Writer) {
	fmt.Fprintln(w, "Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC")
	for _, s := range summaries {
		fmt.Fprintf(w, "%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
			s.Name, s.Lines, s.Code, s.Comment, s.Blank,
			s.Complexity, s.Bytes, s.Count, s.ULOC)
	}
}

func formatClocYAML(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	totalFiles := int64(0)
	totalLines := int64(0)
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
	}
	filesPerSec := int64(0)
	linesPerSec := int64(0)
	if elapsed > 0 {
		filesPerSec = int64(float64(totalFiles) / elapsed)
		linesPerSec = int64(float64(totalLines) / elapsed)
	}
	fmt.Fprintf(w, "# https://github.com/boyter/scc/\n")
	fmt.Fprintf(w, "header:\n")
	fmt.Fprintf(w, "  url: https://github.com/boyter/scc/\n")
	fmt.Fprintf(w, "  version: 3.7.0\n")
	fmt.Fprintf(w, "  elapsed_seconds: %.3f\n", elapsed)
	fmt.Fprintf(w, "  n_files: %d\n", totalFiles)
	fmt.Fprintf(w, "  n_lines: %d\n", totalLines)
	fmt.Fprintf(w, "  files_per_second: %d\n", filesPerSec)
	fmt.Fprintf(w, "  lines_per_second: %d\n", linesPerSec)
	for _, s := range summaries {
		fmt.Fprintf(w, "%s:\n", s.Name)
		fmt.Fprintf(w, "  name: %s\n", s.Name)
		fmt.Fprintf(w, "  code: %d\n", s.Code)
		fmt.Fprintf(w, "  comment: %d\n", s.Comment)
		fmt.Fprintf(w, "  blank: %d\n", s.Blank)
		fmt.Fprintf(w, "  nFiles: %d\n", s.Count)
	}
	// SUM
	totalCode := int64(0)
	totalComment := int64(0)
	totalBlank := int64(0)
	for _, s := range summaries {
		totalCode += s.Code
		totalComment += s.Comment
		totalBlank += s.Blank
	}
	fmt.Fprintf(w, "SUM:\n")
	fmt.Fprintf(w, "  code: %d\n", totalCode)
	fmt.Fprintf(w, "  comment: %d\n", totalComment)
	fmt.Fprintf(w, "  blank: %d\n", totalBlank)
	fmt.Fprintf(w, "  nFiles: %d\n", totalFiles)
}

func formatHTML(summaries []*LanguageSummary, opts *Options, w io.Writer) {
	fmt.Fprintf(w, `<html lang="en"><head><meta charset="utf-8" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body><table id="scc-table">`)
	fmt.Fprintf(w, "\n")
	formatHTMLTable(summaries, opts, w)
	fmt.Fprintf(w, "</table></body></html>")
}

func formatHTMLTable(summaries []*LanguageSummary, opts *Options, w io.Writer) {
	fmt.Fprintf(w, "\t<thead><tr>\n")
	fmt.Fprintf(w, "\t\t<th>Language</th>\n")
	fmt.Fprintf(w, "\t\t<th>Files</th>\n")
	fmt.Fprintf(w, "\t\t<th>Lines</th>\n")
	fmt.Fprintf(w, "\t\t<th>Blank</th>\n")
	fmt.Fprintf(w, "\t\t<th>Comment</th>\n")
	fmt.Fprintf(w, "\t\t<th>Code</th>\n")
	fmt.Fprintf(w, "\t\t<th>Complexity</th>\n")
	fmt.Fprintf(w, "\t\t<th>Bytes</th>\n")
	fmt.Fprintf(w, "\t\t<th>Uloc</th>\n")
	fmt.Fprintf(w, "\t</tr></thead>\n")
	fmt.Fprintf(w, "\t<tbody>")
	for _, s := range summaries {
		fmt.Fprintf(w, "<tr>\n")
		fmt.Fprintf(w, "\t\t<th>%s</th>\n", s.Name)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.Count)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.Lines)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.Blank)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.Comment)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.Code)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.Complexity)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.Bytes)
		fmt.Fprintf(w, "\t\t<th>%d</th>\n", s.ULOC)
		fmt.Fprintf(w, "\t</tr>")
	}
	fmt.Fprintf(w, "</tbody>\n")

	// Total row
	totalFiles := int64(0)
	totalLines := int64(0)
	totalBlank := int64(0)
	totalComment := int64(0)
	totalCode := int64(0)
	totalComplexity := int64(0)
	totalBytes := int64(0)
	totalULOC := int64(0)
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
		totalBlank += s.Blank
		totalComment += s.Comment
		totalCode += s.Code
		totalComplexity += s.Complexity
		totalBytes += s.Bytes
		totalULOC += s.ULOC
	}
	fmt.Fprintf(w, "\t<tfoot><tr>\n")
	fmt.Fprintf(w, "\t\t<th>Total</th>\n")
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalFiles)
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalLines)
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalBlank)
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalComment)
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalCode)
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalComplexity)
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalBytes)
	fmt.Fprintf(w, "\t\t<th>%d</th>\n", totalULOC)
	fmt.Fprintf(w, "\t</tr></tfoot>\n")
}

func formatSQL(summaries []*LanguageSummary, opts *Options, w io.Writer) {
	projectName := opts.SQLProject
	if projectName == "" && len(opts.Paths) > 0 {
		projectName = opts.Paths[0]
	}

	fmt.Fprintf(w, "create table metadata (   -- github.com/boyter/scc v 3.7.0\n")
	fmt.Fprintf(w, "             timestamp text,\n")
	fmt.Fprintf(w, "             Project   text,\n")
	fmt.Fprintf(w, "             elapsed_s real,\n")
	fmt.Fprintf(w, "             estimated_cost real,\n")
	fmt.Fprintf(w, "             estimated_schedule_months real,\n")
	fmt.Fprintf(w, "             estimated_people real);\n")
	fmt.Fprintf(w, "create table t        (\n")
	fmt.Fprintf(w, "             Project       text   ,\n")
	fmt.Fprintf(w, "             Language      text   ,\n")
	fmt.Fprintf(w, "             File          text   ,\n")
	fmt.Fprintf(w, "             File_dirname  text   ,\n")
	fmt.Fprintf(w, "             File_basename text   ,\n")
	fmt.Fprintf(w, "             nByte         integer,\n")
	fmt.Fprintf(w, "             nBlank        integer,\n")
	fmt.Fprintf(w, "             nComment      integer,\n")
	fmt.Fprintf(w, "             nCode         integer,\n")
	fmt.Fprintf(w, "             nComplexity   integer,\n")
	fmt.Fprintf(w, "             nUloc         integer    \n")
	fmt.Fprintf(w, ");\n")
	fmt.Fprintf(w, "begin transaction;\n")

	for _, s := range summaries {
		for _, f := range s.Files {
			dir := f.Filename
			base := ""
			if idx := strings.LastIndex(f.Filename, "/"); idx >= 0 {
				dir = f.Filename[:idx+1]
				base = f.Filename[idx+1:]
			}
			fmt.Fprintf(w, "insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n",
				sqlEscape(projectName),
				sqlEscape(s.Name),
				sqlEscape(f.Filename),
				sqlEscape(dir),
				sqlEscape(base),
				f.Bytes,
				f.Blanks,
				f.Comments,
				f.Code,
				f.Complexity,
				ulocForFile(f),
			)
		}
	}
	fmt.Fprintf(w, "commit;\n")

	// Metadata
	cocomo := CalcCocomo(totalCodeLines(summaries), opts)
	now := time.Now().Format("2006-01-02 15:04:05")
	elapsed := 0.001 // placeholder
	fmt.Fprintf(w, "begin transaction;\n")
	fmt.Fprintf(w, "insert into metadata values('%s', '%s', %f, %f, %f, %f);\n",
		now, sqlEscape(projectName), elapsed,
		cocomo.EstimatedCost, cocomo.ScheduleMonths, cocomo.PeopleRequired)
	fmt.Fprintf(w, "commit;")
}

func formatSQLInsert(summaries []*LanguageSummary, opts *Options, w io.Writer) {
	projectName := opts.SQLProject
	if projectName == "" && len(opts.Paths) > 0 {
		projectName = opts.Paths[0]
	}

	fmt.Fprintf(w, "begin transaction;\n")
	for _, s := range summaries {
		for _, f := range s.Files {
			dir := f.Filename
			base := ""
			if idx := strings.LastIndex(f.Filename, "/"); idx >= 0 {
				dir = f.Filename[:idx+1]
				base = f.Filename[idx+1:]
			}
			fmt.Fprintf(w, "insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n",
				sqlEscape(projectName),
				sqlEscape(s.Name),
				sqlEscape(f.Filename),
				sqlEscape(dir),
				sqlEscape(base),
				f.Bytes,
				f.Blanks,
				f.Comments,
				f.Code,
				f.Complexity,
				ulocForFile(f),
			)
		}
	}
	fmt.Fprintf(w, "commit;")
}

func sqlEscape(s string) string {
	return strings.ReplaceAll(s, "'", "''")
}

func ulocForFile(f *FileResult) int64 {
	if f.LineHashes != nil {
		return int64(len(f.LineHashes))
	}
	return 0
}

func formatOpenMetrics(summaries []*LanguageSummary, w io.Writer) {
	fmt.Fprintf(w, "# TYPE scc_files gauge\n")
	fmt.Fprintf(w, "# HELP scc_files Number of sourcecode files.\n")
	fmt.Fprintf(w, "# TYPE scc_lines gauge\n")
	fmt.Fprintf(w, "# HELP scc_lines Number of lines.\n")
	fmt.Fprintf(w, "# TYPE scc_code gauge\n")
	fmt.Fprintf(w, "# HELP scc_code Number of lines of actual code.\n")
	fmt.Fprintf(w, "# TYPE scc_comments gauge\n")
	fmt.Fprintf(w, "# HELP scc_comments Number of comments.\n")
	fmt.Fprintf(w, "# TYPE scc_blanks gauge\n")
	fmt.Fprintf(w, "# HELP scc_blanks Number of blank lines.\n")
	fmt.Fprintf(w, "# TYPE scc_complexity gauge\n")
	fmt.Fprintf(w, "# HELP scc_complexity Code complexity.\n")
	fmt.Fprintf(w, "# TYPE scc_bytes gauge\n")
	fmt.Fprintf(w, "# UNIT scc_bytes bytes\n")
	fmt.Fprintf(w, "# HELP scc_bytes Size in bytes.\n")
	for _, s := range summaries {
		fmt.Fprintf(w, "scc_files{language=\"%s\"} %d\n", s.Name, s.Count)
		fmt.Fprintf(w, "scc_lines{language=\"%s\"} %d\n", s.Name, s.Lines)
		fmt.Fprintf(w, "scc_code{language=\"%s\"} %d\n", s.Name, s.Code)
		fmt.Fprintf(w, "scc_comments{language=\"%s\"} %d\n", s.Name, s.Comment)
		fmt.Fprintf(w, "scc_blanks{language=\"%s\"} %d\n", s.Name, s.Blank)
		fmt.Fprintf(w, "scc_complexity{language=\"%s\"} %d\n", s.Name, s.Complexity)
		fmt.Fprintf(w, "scc_bytes{language=\"%s\"} %d\n", s.Name, s.Bytes)
	}
}

// Tabular format helpers
func getBorderChar(opts *Options) string {
	if opts.CI {
		return "-"
	}
	return "\u2500"
}

func getBorderVert(opts *Options) string {
	if opts.CI {
		return "|"
	}
	return "\u2502"
}

func makeBorder(width int, opts *Options) string {
	ch := getBorderChar(opts)
	result := ""
	for i := 0; i < width; i++ {
		result += ch
	}
	return result
}

func formatTabular(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	isWide := opts.Wide || opts.Format == "wide"
	showULOC := opts.TrackULOC
	showDryness := opts.TrackDryness
	showCharacter := opts.TrackCharacter
	showPercent := opts.Percent

	// Calculate column widths
	langWidth := 20
	for _, s := range summaries {
		if len(s.Name) > langWidth {
			langWidth = len(s.Name)
		}
	}

	// Build header
	var headerCols []string
	var widths []int

	if !isWide {
		headerCols = []string{"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"}
		widths = []int{langWidth, 9, 9, 9, 9, 9, 12}
	} else {
		headerCols = []string{"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Complexity/Lines"}
		// wider columns for wide format
		if langWidth < 38 {
			langWidth = 38
		}
		widths = []int{langWidth, 9, 9, 9, 9, 9, 11, 16}
	}

	if showULOC || showDryness {
		// Replace Complexity with ULOC or Dryness
		if showDryness {
			headerCols[len(headerCols)-1] = "Complexity"
			headerCols = append(headerCols, "DRYness")
			widths = append(widths, 12)
		} else {
			headerCols[len(headerCols)-1] = "Complexity"
			headerCols = append(headerCols, "ULOC")
			widths = append(widths, 9)
		}
	}

	// Calculate total line width
	totalWidth := 1 // padding
	for i, w2 := range widths {
		totalWidth += w2 + 1
		_ = i
	}
	// Actually compute based on actual column content

	// Format a row
	formatRow := func(cols []string) string {
		var sb strings.Builder
		for i, col := range cols {
			w2 := widths[i]
			if i == 0 {
				// Left align
				sb.WriteString(fmt.Sprintf("%-*s", w2, col))
			} else {
				// Right align
				sb.WriteString(fmt.Sprintf("%*s", w2, col))
			}
			if i < len(cols)-1 {
				sb.WriteString(" ")
			}
		}
		return sb.String()
	}

	headerLine := formatRow(headerCols)
	borderWidth := len(headerLine)
	border := makeBorder(borderWidth, opts)

	printBorder := func() {
		if !opts.NoHBorder {
			fmt.Fprintln(w, border)
		}
	}

	printBorder()
	fmt.Fprintln(w, headerLine)
	printBorder()

	// Print each language
	for _, s := range summaries {
		var row []string
		if !isWide {
			row = []string{
				s.Name,
				formatInt(s.Count),
				formatInt(s.Lines),
				formatInt(s.Blank),
				formatInt(s.Comment),
				formatInt(s.Code),
				formatInt(s.Complexity),
			}
		} else {
			var complPerLine string
			if s.Lines > 0 {
				complPerLine = fmt.Sprintf("%.2f", float64(s.Complexity)/float64(s.Lines))
			} else {
				complPerLine = "0.00"
			}
			row = []string{
				s.Name,
				formatInt(s.Count),
				formatInt(s.Lines),
				formatInt(s.Blank),
				formatInt(s.Comment),
				formatInt(s.Code),
				formatInt(s.Complexity),
				complPerLine,
			}
		}
		if showDryness {
			row = append(row, fmt.Sprintf("%.1f%%", dryness(s)*100))
		} else if showULOC {
			row = append(row, formatInt(s.ULOC))
		}
		fmt.Fprintln(w, formatRow(row))

		if showPercent {
			// Print percentages
			printPercentRow(summaries, s, row, widths, opts, w)
		}

		if showCharacter && s.LineLength != nil {
			charRow := make([]string, len(row))
			for i := range charRow {
				charRow[i] = ""
			}
			charRow[0] = "MaxLine / MeanLine"
			charRow[len(charRow)-2] = strconv.Itoa(s.LineLength.Max)
			charRow[len(charRow)-1] = strconv.Itoa(int(math.Round(s.LineLength.Mean)))
			fmt.Fprintln(w, formatRow(charRow))
		}

		if showULOC && !showDryness && s.ULOC > 0 {
			ulocRow := make([]string, len(row))
			for i := range ulocRow {
				ulocRow[i] = ""
			}
			ulocRow[0] = "(ULOC)"
			ulocRow[2] = formatInt(s.ULOC)
			fmt.Fprintln(w, formatRow(ulocRow))
			printBorder()
		}
	}

	printBorder()

	// Print by-file if enabled
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				var frow []string
				if !isWide {
					frow = []string{
						f.Filename,
						"",
						formatInt(f.Lines),
						formatInt(f.Blanks),
						formatInt(f.Comments),
						formatInt(f.Code),
						formatInt(f.Complexity),
					}
				} else {
					var cpl string
					if f.Lines > 0 {
						cpl = fmt.Sprintf("%.2f", float64(f.Complexity)/float64(f.Lines))
					} else {
						cpl = "0.00"
					}
					frow = []string{
						f.Filename,
						"",
						formatInt(f.Lines),
						formatInt(f.Blanks),
						formatInt(f.Comments),
						formatInt(f.Code),
						formatInt(f.Complexity),
						cpl,
					}
				}
				fmt.Fprintln(w, formatRow(frow))
			}
			printBorder()
		}
	}

	// Total row
	totalFiles := int64(0)
	totalLines := int64(0)
	totalBlanks := int64(0)
	totalComments := int64(0)
	totalCode := int64(0)
	totalComplexity := int64(0)
	totalULOC := int64(0)
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
		totalBlanks += s.Blank
		totalComments += s.Comment
		totalCode += s.Code
		totalComplexity += s.Complexity
		totalULOC += s.ULOC
	}

	var totalRow []string
	if !isWide {
		totalRow = []string{
			"Total",
			formatInt(totalFiles),
			formatInt(totalLines),
			formatInt(totalBlanks),
			formatInt(totalComments),
			formatInt(totalCode),
			formatInt(totalComplexity),
		}
	} else {
		var cpl string
		if totalLines > 0 {
			cpl = fmt.Sprintf("%.2f", float64(totalComplexity)/float64(totalLines))
		} else {
			cpl = "0.00"
		}
		totalRow = []string{
			"Total",
			formatInt(totalFiles),
			formatInt(totalLines),
			formatInt(totalBlanks),
			formatInt(totalComments),
			formatInt(totalCode),
			formatInt(totalComplexity),
			cpl,
		}
	}
	if showDryness {
		totalRow = append(totalRow, "")
	} else if showULOC {
		totalRow = append(totalRow, formatInt(totalULOC))
	}
	fmt.Fprintln(w, formatRow(totalRow))
	printBorder()

	// ULOC summary
	if showULOC && !showDryness {
		ulocTotal := int64(0)
		for _, s := range summaries {
			ulocTotal += s.ULOC
		}
		ulocSummaryRow := make([]string, len(totalRow))
		for i := range ulocSummaryRow {
			ulocSummaryRow[i] = ""
		}
		ulocSummaryRow[0] = "Unique Lines of Code (ULOC)"
		ulocSummaryRow[2] = formatInt(ulocTotal)
		fmt.Fprintln(w, formatRow(ulocSummaryRow))
		printBorder()
	}

	if showDryness {
		ulocTotal := int64(0)
		for _, s := range summaries {
			ulocTotal += s.ULOC
		}
		// Print ULOC and dryness
		ulocSummaryRow := make([]string, len(totalRow))
		for i := range ulocSummaryRow {
			ulocSummaryRow[i] = ""
		}
		ulocSummaryRow[0] = "Unique Lines of Code (ULOC)"
		ulocSummaryRow[2] = formatInt(ulocTotal)
		fmt.Fprintln(w, formatRow(ulocSummaryRow))

		// Dryness overall
		var totalDryness float64
		if totalCode > 0 && ulocTotal > 0 {
			totalDryness = float64(ulocTotal) / float64(totalCode)
		}
		drynessRow := make([]string, len(totalRow))
		for i := range drynessRow {
			drynessRow[i] = ""
		}
