func formatInt(n int64) string {
	if n == 0 {
		return "0"
	}
	// Add commas
	s := strconv.FormatInt(n, 10)
	if n < 0 {
		s = s[1:]
	}
	result := ""
	for i, c := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			result += ","
		}
		result += string(c)
	}
	if n < 0 {
		return "-" + result
	}
	return result
}

