	fmt.Fprintf(w, "             estimated_people real);\n")
	fmt.Fprintf(w, "create table t        (\n")
	fmt.Fprintf(w, "             Project       text   ,\n")
	fmt.Fprintf(w, "             Language      text   ,\n")
	fmt.Fprintf(w, "             File          text   ,\n")
	fmt.Fprintf(w, "             File_dirname  text   ,\n")
	fmt.Fprintf(w, "             File_basename text   ,\n")
	fmt.Fprintf(w, "             nByte         integer,\n")
	fmt.Fprintf(w, "             nBlank        integer,\n")
	fmt.Fprintf(w, "             nComment      integer,\n")
	fmt.Fprintf(w, "             nCode         integer,\n")
	fmt.Fprintf(w, "             nComplexity   integer,\n")
	fmt.Fprintf(w, "             nUloc         integer    \n")
	fmt.Fprintf(w, ");\n")
	fmt.Fprintf(w, "begin transaction;\n")

	for _, s := range summaries {
		for _, f := range s.Files {
			dir := f.Filename
			base := ""
			if idx := strings.LastIndex(f.Filename, "/"); idx >= 0 {
				dir = f.Filename[:idx+1]
				base = f.Filename[idx+1:]
			}
			fmt.Fprintf(w, "insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n",
				sqlEscape(projectName),
				sqlEscape(s.Name),
				sqlEscape(f.Filename),
				sqlEscape(dir),
				sqlEscape(base),
				f.Bytes,
				f.Blanks,
				f.Comments,
				f.Code,
				f.Complexity,
				ulocForFile(f),
			)
		}
	}
	fmt.Fprintf(w, "commit;\n")

	// Metadata
	cocomo := CalcCocomo(totalCodeLines(summaries), opts)
	now := time.Now().Format("2006-01-02 15:04:05")
	elapsed := 0.001 // placeholder
	fmt.Fprintf(w, "begin transaction;\n")
	fmt.Fprintf(w, "insert into metadata values('%s', '%s', %f, %f, %f, %f);\n",
		now, sqlEscape(projectName), elapsed,
		cocomo.EstimatedCost, cocomo.ScheduleMonths, cocomo.PeopleRequired)
	fmt.Fprintf(w, "commit;")
}

func formatSQLInsert(summaries []*LanguageSummary, opts *Options, w io.Writer) {
	projectName := opts.SQLProject
	if projectName == "" && len(opts.Paths) > 0 {
		projectName = opts.Paths[0]
	}

	fmt.Fprintf(w, "begin transaction;\n")
	for _, s := range summaries {
		for _, f := range s.Files {
			dir := f.Filename
			base := ""
			if idx := strings.LastIndex(f.Filename, "/"); idx >= 0 {
				dir = f.Filename[:idx+1]
				base = f.Filename[idx+1:]
			}
			fmt.Fprintf(w, "insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n",
				sqlEscape(projectName),
				sqlEscape(s.Name),
				sqlEscape(f.Filename),
				sqlEscape(dir),
				sqlEscape(base),
				f.Bytes,
				f.Blanks,
				f.Comments,
				f.Code,
				f.Complexity,
				ulocForFile(f),
			)
		}
	}
	fmt.Fprintf(w, "commit;")
}

func sqlEscape(s string) string {
	return strings.ReplaceAll(s, "'", "''")
}

func ulocForFile(f *FileResult) int64 {
	if f.LineHashes != nil {
		return int64(len(f.LineHashes))
	}
	return 0
}

