						formatInt(f.Blanks),
						formatInt(f.Comments),
						formatInt(f.Code),
						formatInt(f.Complexity),
					}
				} else {
					var cpl string
					if f.Lines > 0 {
						cpl = fmt.Sprintf("%.2f", float64(f.Complexity)/float64(f.Lines))
					} else {
						cpl = "0.00"
					}
					frow = []string{
						f.Filename,
						"",
						formatInt(f.Lines),
						formatInt(f.Blanks),
						formatInt(f.Comments),
						formatInt(f.Code),
						formatInt(f.Complexity),
						cpl,
					}
				}
