	}

	// Total row
	totalFiles := int64(0)
	totalLines := int64(0)
	totalBlanks := int64(0)
	totalComments := int64(0)
	totalCode := int64(0)
	totalComplexity := int64(0)
	totalULOC := int64(0)
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
		totalBlanks += s.Blank
		totalComments += s.Comment
		totalCode += s.Code
		totalComplexity += s.Complexity
		totalULOC += s.ULOC
	}

	var totalRow []string
	if !isWide {
		totalRow = []string{
			"Total",
			formatInt(totalFiles),
			formatInt(totalLines),
			formatInt(totalBlanks),
			formatInt(totalComments),
			formatInt(totalCode),
			formatInt(totalComplexity),
		}
	} else {
		var cpl string
		if totalLines > 0 {
			cpl = fmt.Sprintf("%.2f", float64(totalComplexity)/float64(totalLines))
		} else {
			cpl = "0.00"
		}
		totalRow = []string{
			"Total",
			formatInt(totalFiles),
			formatInt(totalLines),
			formatInt(totalBlanks),
			formatInt(totalComments),
			formatInt(totalCode),
			formatInt(totalComplexity),
