// Tabular format helpers
func getBorderChar(opts *Options) string {
	if opts.CI {
		return "-"
	}
	return "\u2500"
}

func getBorderVert(opts *Options) string {
	if opts.CI {
		return "|"
	}
	return "\u2502"
}

func makeBorder(width int, opts *Options) string {
	ch := getBorderChar(opts)
	result := ""
	for i := 0; i < width; i++ {
		result += ch
	}
	return result
}

func formatTabular(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	isWide := opts.Wide || opts.Format == "wide"
	showULOC := opts.TrackULOC
	showDryness := opts.TrackDryness
	showCharacter := opts.TrackCharacter
	showPercent := opts.Percent

	// Calculate column widths
	langWidth := 20
	for _, s := range summaries {
		if len(s.Name) > langWidth {
			langWidth = len(s.Name)
		}
	}

	// Build header
	var headerCols []string
	var widths []int

	if !isWide {
		headerCols = []string{"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"}
		widths = []int{langWidth, 9, 9, 9, 9, 9, 12}
	} else {
		headerCols = []string{"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Complexity/Lines"}
		// wider columns for wide format
		if langWidth < 38 {
			langWidth = 38
		}
		widths = []int{langWidth, 9, 9, 9, 9, 9, 11, 16}
	}

	if showULOC || showDryness {
		// Replace Complexity with ULOC or Dryness
		if showDryness {
			headerCols[len(headerCols)-1] = "Complexity"
			headerCols = append(headerCols, "DRYness")
			widths = append(widths, 12)
		} else {
			headerCols[len(headerCols)-1] = "Complexity"
			headerCols = append(headerCols, "ULOC")
			widths = append(widths, 9)
		}
	}

	// Calculate total line width
	totalWidth := 1 // padding
	for i, w2 := range widths {
		totalWidth += w2 + 1
		_ = i
	}
	// Actually compute based on actual column content

	// Format a row
	formatRow := func(cols []string) string {
		var sb strings.Builder
		for i, col := range cols {
			w2 := widths[i]
			if i == 0 {
				// Left align
				sb.WriteString(fmt.Sprintf("%-*s", w2, col))
			} else {
				// Right align
				sb.WriteString(fmt.Sprintf("%*s", w2, col))
			}
			if i < len(cols)-1 {
				sb.WriteString(" ")
			}
		}
		return sb.String()
	}

	headerLine := formatRow(headerCols)
	borderWidth := len(headerLine)
	border := makeBorder(borderWidth, opts)

	printBorder := func() {
		if !opts.NoHBorder {
			fmt.Fprintln(w, border)
		}
	}

	printBorder()
	fmt.Fprintln(w, headerLine)
	printBorder()

	// Print each language
	for _, s := range summaries {
		var row []string
		if !isWide {
			row = []string{
				s.Name,
				formatInt(s.Count),
				formatInt(s.Lines),
				formatInt(s.Blank),
				formatInt(s.Comment),
				formatInt(s.Code),
				formatInt(s.Complexity),
			}
		} else {
			var complPerLine string
			if s.Lines > 0 {
				complPerLine = fmt.Sprintf("%.2f", float64(s.Complexity)/float64(s.Lines))
			} else {
				complPerLine = "0.00"
			}
			row = []string{
				s.Name,
				formatInt(s.Count),
				formatInt(s.Lines),
				formatInt(s.Blank),
				formatInt(s.Comment),
				formatInt(s.Code),
				formatInt(s.Complexity),
				complPerLine,
			}
		}
		if showDryness {
			row = append(row, fmt.Sprintf("%.1f%%", dryness(s)*100))
		} else if showULOC {
			row = append(row, formatInt(s.ULOC))
		}
		fmt.Fprintln(w, formatRow(row))

		if showPercent {
			// Print percentages
			printPercentRow(summaries, s, row, widths, opts, w)
		}

		if showCharacter && s.LineLength != nil {
			charRow := make([]string, len(row))
			for i := range charRow {
				charRow[i] = ""
			}
			charRow[0] = "MaxLine / MeanLine"
			charRow[len(charRow)-2] = strconv.Itoa(s.LineLength.Max)
			charRow[len(charRow)-1] = strconv.Itoa(int(math.Round(s.LineLength.Mean)))
			fmt.Fprintln(w, formatRow(charRow))
		}

		if showULOC && !showDryness && s.ULOC > 0 {
			ulocRow := make([]string, len(row))
			for i := range ulocRow {
				ulocRow[i] = ""
			}
			ulocRow[0] = "(ULOC)"
			ulocRow[2] = formatInt(s.ULOC)
			fmt.Fprintln(w, formatRow(ulocRow))
			printBorder()
		}
	}

	printBorder()

	// Print by-file if enabled
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				var frow []string
				if !isWide {
					frow = []string{
						f.Filename,
						"",
						formatInt(f.Lines),
						formatInt(f.Blanks),
						formatInt(f.Comments),
						formatInt(f.Code),
						formatInt(f.Complexity),
					}
				} else {
					var cpl string
					if f.Lines > 0 {
						cpl = fmt.Sprintf("%.2f", float64(f.Complexity)/float64(f.Lines))
					} else {
						cpl = "0.00"
					}
					frow = []string{
						f.Filename,
						"",
						formatInt(f.Lines),
						formatInt(f.Blanks),
						formatInt(f.Comments),
						formatInt(f.Code),
						formatInt(f.Complexity),
						cpl,
					}
				}
				fmt.Fprintln(w, formatRow(frow))
			}
			printBorder()
		}
	}

	// Total row
	totalFiles := int64(0)
	totalLines := int64(0)
	totalBlanks := int64(0)
	totalComments := int64(0)
	totalCode := int64(0)
	totalComplexity := int64(0)
	totalULOC := int64(0)
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
		totalBlanks += s.Blank
		totalComments += s.Comment
		totalCode += s.Code
		totalComplexity += s.Complexity
		totalULOC += s.ULOC
	}

	var totalRow []string
	if !isWide {
		totalRow = []string{
			"Total",
			formatInt(totalFiles),
			formatInt(totalLines),
			formatInt(totalBlanks),
			formatInt(totalComments),
			formatInt(totalCode),
			formatInt(totalComplexity),
		}
	} else {
		var cpl string
		if totalLines > 0 {
			cpl = fmt.Sprintf("%.2f", float64(totalComplexity)/float64(totalLines))
		} else {
			cpl = "0.00"
		}
		totalRow = []string{
			"Total",
			formatInt(totalFiles),
			formatInt(totalLines),
			formatInt(totalBlanks),
			formatInt(totalComments),
			formatInt(totalCode),
			formatInt(totalComplexity),
			cpl,
		}
	}
	if showDryness {
		totalRow = append(totalRow, "")
	} else if showULOC {
		totalRow = append(totalRow, formatInt(totalULOC))
	}
	fmt.Fprintln(w, formatRow(totalRow))
	printBorder()

	// ULOC summary
	if showULOC && !showDryness {
		ulocTotal := int64(0)
		for _, s := range summaries {
			ulocTotal += s.ULOC
		}
		ulocSummaryRow := make([]string, len(totalRow))
		for i := range ulocSummaryRow {
			ulocSummaryRow[i] = ""
		}
		ulocSummaryRow[0] = "Unique Lines of Code (ULOC)"
		ulocSummaryRow[2] = formatInt(ulocTotal)
		fmt.Fprintln(w, formatRow(ulocSummaryRow))
		printBorder()
	}

	if showDryness {
		ulocTotal := int64(0)
		for _, s := range summaries {
			ulocTotal += s.ULOC
		}
		// Print ULOC and dryness
		ulocSummaryRow := make([]string, len(totalRow))
		for i := range ulocSummaryRow {
			ulocSummaryRow[i] = ""
		}
		ulocSummaryRow[0] = "Unique Lines of Code (ULOC)"
		ulocSummaryRow[2] = formatInt(ulocTotal)
		fmt.Fprintln(w, formatRow(ulocSummaryRow))

		// Dryness overall
		var totalDryness float64
		if totalCode > 0 && ulocTotal > 0 {
			totalDryness = float64(ulocTotal) / float64(totalCode)
		}
		drynessRow := make([]string, len(totalRow))
		for i := range drynessRow {
			drynessRow[i] = ""
		}
		drynessRow[0] = "DRYness %"
		drynessRow[2] = fmt.Sprintf("%.2f", totalDryness)
		fmt.Fprintln(w, formatRow(drynessRow))
		printBorder()
	}

	// COCOMO
	if !opts.NoCocomo {
		cocomo := CalcCocomo(totalCode, opts)
		currencySymbol := opts.CurrencySymbol
		if currencySymbol == "" {
			currencySymbol = "$"
		}
		if !opts.SlocCountFormat {
			fmt.Fprintf(w, "Estimated Cost to Develop (%s) %s%s\n",
				cocomo.ProjectType,
				currencySymbol,
				formatMoney(cocomo.EstimatedCost))
			fmt.Fprintf(w, "Estimated Schedule Effort (%s) %.2f months\n",
				cocomo.ProjectType, cocomo.ScheduleMonths)
			fmt.Fprintf(w, "Estimated People Required (%s) %.2f\n",
				cocomo.ProjectType, cocomo.PeopleRequired)
		} else {
			salary := opts.AvgWage
			if salary == 0 {
				salary = 56286
			}
			overhead := opts.Overhead
			if overhead == 0 {
				overhead = 2.4
			}
			eaf := opts.EAF
			if eaf == 0 {
				eaf = 1.0
			}
			fmt.Fprintf(w, "Total Physical Source Lines of Code (SLOC)                     = %d\n", totalCode)
			fmt.Fprintf(w, "Development Effort Estimate, Person-Years (Person-Months)      = %.2f (%.2f)\n",
				cocomo.Effort/12, cocomo.Effort)
			fmt.Fprintf(w, " (Basic COCOMO model, Person-Months = %.2f*(KSLOC**%.2f)*%.2f)\n",
				getCocomoA(opts), getCocomoB(opts), eaf)
			fmt.Fprintf(w, "Schedule Estimate, Years (Months)                              = %.2f (%.2f)\n",
				cocomo.ScheduleMonths/12, cocomo.ScheduleMonths)
			fmt.Fprintf(w, " (Basic COCOMO model, Months = %.2f*(person-months**%.2f))\n",
				getCocomoC(opts), getCocomoD(opts))
			fmt.Fprintf(w, "Estimated Average Number of Developers (Effort/Schedule)       = %.2f\n",
				cocomo.PeopleRequired)
			fmt.Fprintf(w, "Total Estimated Cost to Develop                                = %s%s\n",
				currencySymbol,
				formatMoney(cocomo.EstimatedCost))
			fmt.Fprintf(w, " (average salary = %s%s/year, overhead = %.2f)\n",
				currencySymbol,
				formatMoneyComma(float64(salary)),
				overhead)
		}
		printBorder()
	}

	if !opts.NoSize {
		sizeStr := formatBytes(totalBytes, opts.SizeUnit)
		fmt.Fprintf(w, "Processed %d bytes, %s\n", totalBytes, sizeStr)
		printBorder()
	} else if opts.Wide {
		// Wide mode always shows processed even without NoSize
	}
}

func printPercentRow(all []*LanguageSummary, s *LanguageSummary, row []string, widths []int, opts *Options, w io.Writer) {
	// Calculate totals
	totalFiles := int64(0)
	totalLines := int64(0)
	totalBlanks := int64(0)
	totalComments := int64(0)
	totalCode := int64(0)
	totalComplexity := int64(0)
	for _, ls := range all {
		totalFiles += ls.Count
		totalLines += ls.Lines
		totalBlanks += ls.Blank
		totalComments += ls.Comment
		totalCode += ls.Code
		totalComplexity += ls.Complexity
	}

	pct := func(part, total int64) string {
		if total == 0 {
			return "NaN%"
		}
		return fmt.Sprintf("%.1f%%", float64(part)/float64(total)*100)
	}

	// Build percent row
	var formatRow func(cols []string) string
	formatRow = func(cols []string) string {
		var sb strings.Builder
		for i, col := range cols {
			w2 := widths[i]
			if i == 0 {
				sb.WriteString(fmt.Sprintf("%-*s", w2, col))
			} else {
				sb.WriteString(fmt.Sprintf("%*s", w2, col))
			}
			if i < len(cols)-1 {
				sb.WriteString(" ")
			}
		}
		return sb.String()
	}

	pctRow := make([]string, len(row))
	pctRow[0] = "Percentage"
	pctRow[1] = pct(s.Count, totalFiles)
	pctRow[2] = pct(s.Lines, totalLines)
	pctRow[3] = pct(s.Blank, totalBlanks)
	pctRow[4] = pct(s.Comment, totalComments)
	pctRow[5] = pct(s.Code, totalCode)
	if len(pctRow) > 6 {
		pctRow[6] = pct(s.Complexity, totalComplexity)
	}

	// Use dashes instead of border char for percent separator
	borderStr := ""
	totalLen := 0
	for _, w2 := range widths {
		totalLen += w2 + 1
	}
	for i := 0; i < totalLen-1; i++ {
		borderStr += "-"
	}

	fmt.Fprintln(w, formatRow(pctRow))
	fmt.Fprintln(w, borderStr)
}

func dryness(s *LanguageSummary) float64 {
	if s.Code == 0 {
		return 0
	}
	return float64(s.ULOC) / float64(s.Code)
}

func totalCodeLines(summaries []*LanguageSummary) int64 {
	total := int64(0)
	for _, s := range summaries {
		total += s.Code
	}
	return total
}

func formatInt(n int64) string {
	if n == 0 {
		return "0"
	}
	// Add commas
	s := strconv.FormatInt(n, 10)
	if n < 0 {
		s = s[1:]
	}
	result := ""
	for i, c := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			result += ","
		}
		result += string(c)
	}
	if n < 0 {
		return "-" + result
	}
	return result
}

func formatMoney(f float64) string {
	return strconv.FormatInt(int64(math.Round(f)), 10)
}

func formatMoneyComma(f float64) string {
	s := strconv.FormatInt(int64(f), 10)
	result := ""
	for i, c := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			result += ","
		}
		result += string(c)
	}
	return result
}

func formatBytes(totalBytes int64, sizeUnit string) string {
	switch strings.ToLower(sizeUnit) {
	case "binary":
		mb := float64(totalBytes) / (1024.0 * 1024.0)
		return fmt.Sprintf("%.3f megabytes (BINARY)", mb)
	case "mixed":
		mb := float64(totalBytes) / (1000.0 * 1024.0)
		return fmt.Sprintf("%.3f megabytes (MIXED)", mb)
	case "xkcd-kb":
		mb := float64(totalBytes) / (1000.0 * 1000.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-KB)", mb)
	case "xkcd-kelly":
		mb := float64(totalBytes) / (1012.0 * 1012.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-KELLY)", mb)
	case "xkcd-imaginary":
		return fmt.Sprintf("¯\\_(ツ)_/¯ megabytes (XKCD-IMAGINARY)")
	case "xkcd-intel":
		mb := float64(totalBytes) / (1000.0 * 1000.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-INTEL)", mb)
	case "xkcd-drive":
		mb := float64(totalBytes) / (1000.0 * 1000.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-DRIVE)", mb)
	case "xkcd-bakers":
		mb := float64(totalBytes) / (1152.0 * 1152.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-BAKERS)", mb)
	default: // si
		mb := float64(totalBytes) / (1000.0 * 1000.0)
		return fmt.Sprintf("%.3f megabytes (SI)", mb)
	}
}

func getXKCDNote(sizeUnit string) string {
	switch strings.ToLower(sizeUnit) {
	case "xkcd-kb":
		return "1000 bytes during leap years, 1024 otherwise"
	case "xkcd-kelly":
		return "compromise between 1000 and 1024 bytes"
	case "xkcd-imaginary":
		return "used in quantum computing"
	case "xkcd-intel":
		return "calculated on pentium F.P.U."
	case "xkcd-drive":
		return "shrinks by 4 bytes every year for marketing reasons"
	case "xkcd-bakers":
		return "9 bits to the byte since you're such a good customer"
	}
	return ""
}

