	opts.Verbose = *verbose || *verboseLong
	opts.Wide = *wide || *wideLong

	// Format
	fmtVal := *format
	if *formatLong != "tabular" {
		fmtVal = *formatLong
	}
	if opts.Wide {
		fmtVal = "wide"
	}
	opts.Format = fmtVal

	// Sort
	sortVal := *sortBy
	if *sortByLong != "files" {
		sortVal = *sortByLong
	}
	opts.Sort = sortVal

	// Output
	outVal := *output
	if *outputLong != "" {
		outVal = *outputLong
	}
	opts.Output = outVal

	// Exclude dirs
	if *excludeDir != ".git,.hg,.svn" {
		opts.ExcludeDir = parseCommaSep(*excludeDir)
	}

	// Exclude extensions
	exts := *excludeExt
	if *excludeExtLong != "" {
		exts = *excludeExtLong
	}
	if exts != "" {
		opts.ExcludeExt = parseCommaSep(exts)
	}

	// Exclude files
	excFiles := *excludeFile
	if *excludeFileLong != "package-lock.json,Cargo.lock,yarn.lock,pubspec.lock,Podfile.lock,pnpm-lock.yaml" {
		excFiles = *excludeFileLong
	}
	opts.ExcludeFile = parseCommaSep(excFiles)

	// Include extensions
	inclExts := *includeExt
	if *includeExtLong != "" {
		inclExts = *includeExtLong
	}
	if inclExts != "" {
		opts.IncludeExt = parseCommaSep(inclExts)
	}

	// Not match
	notMatchStr := *notMatch
	if *notMatchLong != "" {
		notMatchStr = *notMatchLong
	}
	if notMatchStr != "" {
		opts.NotMatch = []string{notMatchStr}
	}

	// Generated markers
	if *generatedMarkers != "do not edit,<auto-generated />" {
		opts.GeneratedMarkers = parseCommaSep(*generatedMarkers)
	}

	// Paths
	args := fs.Args()
	if len(args) == 0 {
		args = []string{"."}
	}
	opts.Paths = args

	// Run the main processing
	runSCC(opts)
}

func runSCC(opts *Options) {
	startTime := time.Now()

	// Apply count-as mapping
	countAsMap := parseCountAs(opts.CountAs)

	// Walk directories and collect files
	files, err := WalkDirectory(opts.Paths, opts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error walking directory: %v\n", err)
		os.Exit(1)
	}

	// Process each file
	var results []*FileResult
	totalBytes := int64(0)

	for _, filename := range files {
		// Read file to detect language
		content, err := os.ReadFile(filename)
		if err != nil {
			if opts.Verbose {
				fmt.Fprintf(os.Stderr, "Warning: cannot read %s: %v\n", filename, err)
			}
			continue
		}

		// Check extension filter
		if len(opts.IncludeExt) > 0 {
			ext := getExtension(filename)
			if !containsIgnoreCase(opts.IncludeExt, ext) {
				continue
			}
		}

		if len(opts.ExcludeExt) > 0 {
			ext := getExtension(filename)
			if containsIgnoreCase(opts.ExcludeExt, ext) {
				continue
			}
		}

		// Detect language
		lang := DetectLanguage(filename, content)

		// Apply count-as mapping
		if lang != nil {
			if mapped, ok := countAsMap[getExtension(filename)]; ok {
				for i := range Languages {
					if strings.EqualFold(Languages[i].Name, mapped) {
						lang = &Languages[i]
						break
					}
				}
			}
		}

		// Apply remap-unknown / remap-all
		if lang == nil && opts.RemapUnknown != "" {
			lang = remapByContent(content, opts.RemapUnknown)
		}
		if opts.RemapAll != "" {
			if l := remapByContent(content, opts.RemapAll); l != nil {
				lang = l
			}
		}

		if lang == nil {
			if opts.Verbose {
				fmt.Fprintf(os.Stderr, "Unknown language for file: %s\n", filename)
			}
			continue
		}

		// Check large file filters
		if opts.NoLarge {
			lineCount := int64(strings.Count(string(content), "\n"))
			if lineCount > int64(opts.LargeLineCount) || int64(len(content)) > int64(opts.LargeByteCount) {
				continue
			}
		}

		result, err := ProcessFile(filename, lang, opts)
		if err != nil {
			if opts.Verbose {
				fmt.Fprintf(os.Stderr, "Warning: error processing %s: %v\n", filename, err)
			}
			continue
		}
		if result == nil {
			continue // binary file
		}

		totalBytes += result.Bytes
		results = append(results, result)
	}

	elapsed := time.Since(startTime).Seconds()

	// Aggregate results
	summaries := AggregateResults(results, opts)

	// Handle no-duplicates
	if opts.NoDuplicates {
		summaries = removeDuplicates(summaries, opts)
	}

	// Determine output writer
	var w = os.Stdout
	if opts.Output != "" {
		f, err := os.Create(opts.Output)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error creating output file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		w = f
	}

	// Handle xkcd note before output
	if opts.Format == "" || opts.Format == "tabular" || opts.Format == "wide" {
		note := getXKCDNote(opts.SizeUnit)
		if note != "" && !opts.NoSize {
			// We'll print it in the tabular formatter
		}
		_ = note
	}

	// Format output
	FormatOutput(summaries, opts, totalBytes, elapsed, w)
}

func getExtension(filename string) string {
	base := filepath.Base(filename)
	lower := strings.ToLower(base)
	// Handle compound extensions
	parts := strings.Split(lower, ".")
	if len(parts) > 2 {
		compound := parts[len(parts)-2] + "." + parts[len(parts)-1]
		return compound
	}
	if idx := strings.LastIndex(lower, "."); idx >= 0 {
		return lower[idx+1:]
	}
	return lower
}

func containsIgnoreCase(slice []string, item string) bool {
	item = strings.ToLower(item)
	for _, s := range slice {
		if strings.ToLower(s) == item {
			return true
		}
	}
	return false
}

func parseCommaSep(s string) []string {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	var result []string
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func parseCountAs(countAs string) map[string]string {
	result := make(map[string]string)
	if countAs == "" {
		return result
	}
	// Format: "jsp:htm,chead:C Header"
	parts := strings.Split(countAs, ",")
	for _, part := range parts {
		kv := strings.SplitN(part, ":", 2)
		if len(kv) == 2 {
			ext := strings.TrimSpace(kv[0])
			lang := strings.TrimSpace(strings.Trim(kv[1], `"`))
			result[ext] = lang
		}
	}
	return result
}

func remapByContent(content []byte, remapStr string) *LanguageDef {
	// Format: "string:Language"
	kv := strings.SplitN(remapStr, ":", 2)
	if len(kv) != 2 {
		return nil
	}
	searchStr := strings.Trim(kv[0], `"`)
	langName := strings.Trim(kv[1], `"`)

	// Check if file contains the search string in first few lines
	lines := strings.SplitN(string(content), "\n", 10)
	for _, line := range lines {
		if strings.Contains(line, searchStr) {
			for i := range Languages {
				if strings.EqualFold(Languages[i].Name, langName) {
					return &Languages[i]
				}
			}
		}
	}
	return nil
}

func removeDuplicates(summaries []*LanguageSummary, opts *Options) []*LanguageSummary {
	// Simple deduplication - track by content hash
	// For now just return as-is
	return summaries
}

