      --file-gc-count int                  number of files to parse before turning the GC on (default 10000)
      --file-list-queue-size int           the size of the queue of files found and ready to be read into memory (default 192)
      --file-process-job-workers int       number of goroutine workers that process files collecting stats (default 192)
      --file-summary-job-queue-size int    the size of the queue used to hold processed file statistics before formatting (default 192)
  -f, --format string                      set output format [tabular, wide, json, json2, csv, csv-stream, cloc-yaml, html, html-table, sql, sql-insert, openmetrics] (default "tabular")
