package main

import (
	"fmt"
	"unicode/utf8"
)

// Simulate go-runewidth truncation
func truncate(s string, w int, tail string) string {
	// Count display width of tail
	tailWidth := stringWidth(tail)
	if stringWidth(s) <= w {
		return s
	}
	total := 0
	for i, r := range s {
		cw := runeWidth(r)
		if total+cw+tailWidth > w {
			return s[:i] + tail
		}
		total += cw
	}
	return s
}

func fillRight(s string, w int) string {
	sw := stringWidth(s)
	for sw < w {
		s += " "
		sw++
	}
	return s
}

func stringWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}

func runeWidth(r rune) int {
	// Simplified: just ASCII = 1, else 2
	if r < 0x20 {
		return 0
	}
	// East Asian wide chars
	if (r >= 0x1100 && r <= 0x115F) ||
		r == 0x2329 || r == 0x232A ||
		(r >= 0x2E80 && r <= 0x303E) ||
		(r >= 0x3040 && r <= 0xA4CF) ||
		(r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) ||
		(r >= 0xFE10 && r <= 0xFE19) ||
