		(r >= 0x1B000 && r <= 0x1B001) ||
		(r >= 0x1F300 && r <= 0x1F64F) ||
		(r >= 0x1F900 && r <= 0x1F9FF) ||
		(r >= 0x20000 && r <= 0x2FFFD) ||
		(r >= 0x30000 && r <= 0x3FFFD) {
		return 2
	}
	return 1
}

func main() {
	names := []string{
		"Extensible Stylesheet Language Transformations",
		"Android Interface Definition Language",
		"Web Services Description Language",
	}

	ellipsis := "…"
	fmt.Printf("runeWidth('…') = %d\n", runeWidth('…'))
	fmt.Printf("len(ellipsis in bytes) = %d\n", len([]byte(ellipsis)))
	fmt.Printf("utf8.RuneCountInString(ellipsis) = %d\n", utf8.RuneCountInString(ellipsis))

	for _, name := range names {
