package main

import (
	"encoding/json"
	"fmt"
	"io"
	"math"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

// LanguageSummary holds aggregated stats for a language
type LanguageSummary struct {
	Name               string        `json:"Name"`
	Bytes              int64         `json:"Bytes"`
	CodeBytes          int64         `json:"CodeBytes"`
	Lines              int64         `json:"Lines"`
	Code               int64         `json:"Code"`
	Comment            int64         `json:"Comment"`
	Blank              int64         `json:"Blank"`
	Complexity         int64         `json:"Complexity"`
	Count              int64         `json:"Count"`
	WeightedComplexity float64       `json:"WeightedComplexity"`
	Files              []*FileResult `json:"Files"`
	LineLength         *LineLengthSummary `json:"LineLength"`
	ULOC               int64         `json:"ULOC"`
}

type LineLengthSummary struct {
	Max  int     `json:"max"`
	Mean float64 `json:"mean"`
}

// runeWidth returns the display width of a rune (simplified go-runewidth behavior)
func runeWidth(r rune) int {
	// Wide characters (CJK etc.)
	if r == 0 {
		return 0
	}
	if r < 0x20 {
		return 0
	}
	if r == 0x00AD || r == 0x200B {
		return 0
	}
	// Wide/Fullwidth characters
	if (r >= 0x1100 && r <= 0x115F) ||
		r == 0x2329 || r == 0x232A ||
		(r >= 0x2E80 && r <= 0x3247) ||
		(r >= 0x3250 && r <= 0x4DBF) ||
		(r >= 0x4E00 && r <= 0xA4C6) ||
		(r >= 0xA960 && r <= 0xA97C) ||
		(r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) ||
		(r >= 0xFE10 && r <= 0xFE19) ||
		(r >= 0xFE30 && r <= 0xFE6F) ||
		(r >= 0xFF01 && r <= 0xFF60) ||
		(r >= 0xFFE0 && r <= 0xFFE6) ||
		(r >= 0x1B000 && r <= 0x1B001) ||
		(r >= 0x1F300 && r <= 0x1F64F) ||
		(r >= 0x1F900 && r <= 0x1F9FF) ||
		(r >= 0x20000 && r <= 0x2FFFD) ||
		(r >= 0x30000 && r <= 0x3FFFD) {
		return 2
	}
	return 1
}

func stringWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}

// truncateName truncates a name to fit within displayWidth, adding '…' if needed
// Uses go-runewidth.Truncate behavior: tail has display width 1 (narrow '…')
func truncateName(name string, displayWidth int) string {
	tail := "…"
	tailWidth := 1 // go-runewidth treats '…' as narrow (width 1) by default
	if stringWidth(name) <= displayWidth {
		return name
	}
	total := 0
	for i, r := range name {
		cw := runeWidth(r)
		if total+cw+tailWidth > displayWidth {
			return name[:i] + tail
		}
		total += cw
	}
	return name
}

// fillRight pads string to displayWidth using spaces
func fillRight(s string, displayWidth int) string {
	sw := stringWidth(s)
	if sw >= displayWidth {
		return s
	}
	return s + strings.Repeat(" ", displayWidth-sw)
}

// formatLanguageName formats a language name for a column of given string width
func formatLanguageName(name string, colWidth int, truncateAt int) string {
	truncated := truncateName(name, truncateAt)
	return fillRight(truncated, colWidth)
}

// FormatOutput writes the output in the requested format
func FormatOutput(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	switch opts.Format {
	case "json":
		formatJSON(summaries, w)
	case "json2":
		formatJSON2(summaries, opts, totalBytes, elapsed, w)
	case "csv":
		formatCSV(summaries, w)
	case "csv-stream":
		formatCSV(summaries, w)
	case "cloc-yaml":
		formatClocYAML(summaries, opts, totalBytes, elapsed, w)
	case "html":
		formatHTML(summaries, opts, w)
	case "html-table":
		fmt.Fprintf(w, `<html lang="en"><head><meta charset="utf-8" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body><table id="scc-table">`)
		fmt.Fprintln(w)
		formatHTMLTableContent(summaries, opts, w)
		fmt.Fprintln(w, "</table></body></html>")
	case "sql":
		formatSQL(summaries, opts, w)
	case "sql-insert":
		formatSQLInsert(summaries, opts, w)
	case "openmetrics":
		formatOpenMetrics(summaries, w)
	default: // tabular or wide
		formatTabular(summaries, opts, totalBytes, elapsed, w)
	}
}

func formatJSON(summaries []*LanguageSummary, w io.Writer) {
	for _, s := range summaries {
		if s.Files == nil {
			s.Files = []*FileResult{}
		}
		if s.LineLength == nil {
			s.LineLength = nil
		}
	}
	data, _ := json.Marshal(summaries)
	fmt.Fprintf(w, "%s", data)
}

func formatJSON2(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	cocomo := CalcCocomo(totalCodeLines(summaries), opts)
	type json2Output struct {
		LanguageSummary         []*LanguageSummary `json:"languageSummary"`
		EstimatedCost           float64            `json:"estimatedCost"`
		EstimatedScheduleMonths float64            `json:"estimatedScheduleMonths"`
		EstimatedPeople         float64            `json:"estimatedPeople"`
	}
	for _, s := range summaries {
		if s.Files == nil {
			s.Files = []*FileResult{}
		}
	}
	out := json2Output{
		LanguageSummary:         summaries,
		EstimatedCost:           cocomo.EstimatedCost,
		EstimatedScheduleMonths: cocomo.ScheduleMonths,
		EstimatedPeople:         cocomo.PeopleRequired,
	}
	data, _ := json.Marshal(out)
	fmt.Fprintf(w, "%s", data)
}

func formatCSV(summaries []*LanguageSummary, w io.Writer) {
	fmt.Fprintln(w, "Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC")
	for _, s := range summaries {
		fmt.Fprintf(w, "%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
			s.Name, s.Lines, s.Code, s.Comment, s.Blank,
			s.Complexity, s.Bytes, s.Count, s.ULOC)
	}
}

func formatClocYAML(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	totalFiles := int64(0)
	totalLines := int64(0)
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
	}
	filesPerSec := int64(0)
	linesPerSec := int64(0)
	if elapsed > 0 {
		filesPerSec = int64(float64(totalFiles) / elapsed)
		linesPerSec = int64(float64(totalLines) / elapsed)
	}
	fmt.Fprintf(w, "# https://github.com/boyter/scc/\n")
	fmt.Fprintf(w, "header:\n")
	fmt.Fprintf(w, "  url: https://github.com/boyter/scc/\n")
	fmt.Fprintf(w, "  version: 3.7.0\n")
	fmt.Fprintf(w, "  elapsed_seconds: %.3f\n", elapsed)
	fmt.Fprintf(w, "  n_files: %d\n", totalFiles)
	fmt.Fprintf(w, "  n_lines: %d\n", totalLines)
	fmt.Fprintf(w, "  files_per_second: %d\n", filesPerSec)
	fmt.Fprintf(w, "  lines_per_second: %d\n", linesPerSec)
	for _, s := range summaries {
		fmt.Fprintf(w, "%s:\n", s.Name)
		fmt.Fprintf(w, "  name: %s\n", s.Name)
		fmt.Fprintf(w, "  code: %d\n", s.Code)
		fmt.Fprintf(w, "  comment: %d\n", s.Comment)
		fmt.Fprintf(w, "  blank: %d\n", s.Blank)
		fmt.Fprintf(w, "  nFiles: %d\n", s.Count)
	}
	totalCode := int64(0)
	totalComment := int64(0)
	totalBlank := int64(0)
	for _, s := range summaries {
		totalCode += s.Code
		totalComment += s.Comment
		totalBlank += s.Blank
	}
	fmt.Fprintf(w, "SUM:\n")
	fmt.Fprintf(w, "  code: %d\n", totalCode)
	fmt.Fprintf(w, "  comment: %d\n", totalComment)
	fmt.Fprintf(w, "  blank: %d\n", totalBlank)
	fmt.Fprintf(w, "  nFiles: %d\n", totalFiles)
}

func formatHTML(summaries []*LanguageSummary, opts *Options, w io.Writer) {
	fmt.Fprintf(w, `<html lang="en"><head><meta charset="utf-8" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body><table id="scc-table">`)
	fmt.Fprintln(w)
	formatHTMLTableContent(summaries, opts, w)
	fmt.Fprintf(w, "</table></body></html>")
}

func formatHTMLTableContent(summaries []*LanguageSummary, opts *Options, w io.Writer) {
	fmt.Fprintf(w, "\t<thead><tr>\n")
	fmt.Fprintf(w, "\t\t<th>Language</th>\n")
	fmt.Fprintf(w, "\t\t<th>Files</th>\n")
