func formatBytesStr(totalBytes int64, sizeUnit string) string {
	switch strings.ToLower(sizeUnit) {
	case "binary":
		mb := float64(totalBytes) / (1024.0 * 1024.0)
		return fmt.Sprintf("%.3f megabytes (BINARY)", mb)
	case "mixed":
		mb := float64(totalBytes) / (1000.0 * 1024.0)
		return fmt.Sprintf("%.3f megabytes (MIXED)", mb)
	case "xkcd-kb":
		mb := float64(totalBytes) / (1000.0 * 1000.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-KB)", mb)
	case "xkcd-kelly":
		mb := float64(totalBytes) / (1012.0 * 1012.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-KELLY)", mb)
	case "xkcd-imaginary":
		return "\u00af\\_(ツ)_/\u00af megabytes (XKCD-IMAGINARY)"
	case "xkcd-intel":
		mb := float64(totalBytes) / (1000.0 * 1000.0)
		return fmt.Sprintf("%.3f megabytes (XKCD-INTEL)", mb)
	case "xkcd-drive":
