// AggregateResults aggregates FileResults into LanguageSummaries
func AggregateResults(results []*FileResult, opts *Options) []*LanguageSummary {
	byLang := make(map[string]*LanguageSummary)

	for _, r := range results {
		if r == nil {
			continue
		}
		s, ok := byLang[r.Language]
		if !ok {
			s = &LanguageSummary{Name: r.Language}
			byLang[r.Language] = s
		}
		s.Bytes += r.Bytes
		s.Lines += r.Lines
		s.Code += r.Code
		s.Comment += r.Comments
		s.Blank += r.Blanks
		s.Complexity += r.Complexity
		s.Count++

		if opts.ByFile || opts.Format == "sql" || opts.Format == "sql-insert" {
			s.Files = append(s.Files, r)
		}
	}

	// For ULOC, compute unique lines across all files per language
	if opts.TrackULOC {
		langHashes := make(map[string]map[string]bool)
		for _, r := range results {
			if r == nil || r.LineHashes == nil {
				continue
			}
			if _, ok := langHashes[r.Language]; !ok {
				langHashes[r.Language] = make(map[string]bool)
			}
			for k := range r.LineHashes {
				langHashes[r.Language][k] = true
			}
		}
		for lang, hashes := range langHashes {
			if s, ok := byLang[lang]; ok {
				s.ULOC = int64(len(hashes))
			}
		}
	}

	if opts.TrackCharacter {
		type charStats struct {
			maxLine int
			sumLine int64
			cnt     int64
		}
		stats := make(map[string]*charStats)
		for _, r := range results {
			if r == nil {
				continue
			}
			if _, ok := stats[r.Language]; !ok {
				stats[r.Language] = &charStats{}
			}
			st := stats[r.Language]
			if r.MaxLine > st.maxLine {
				st.maxLine = r.MaxLine
			}
			st.sumLine += r.SumLine
			st.cnt += r.Lines
		}
		for lang, st := range stats {
			if s, ok := byLang[lang]; ok {
				mean := 0.0
				if st.cnt > 0 {
					mean = float64(st.sumLine) / float64(st.cnt)
				}
				s.LineLength = &LineLengthSummary{
					Max:  st.maxLine,
					Mean: mean,
				}
			}
		}
	}

	// Sort files within each language
	for _, s := range byLang {
		sort.Slice(s.Files, func(i, j int) bool {
			return s.Files[i].Filename < s.Files[j].Filename
		})
	}

	// Convert map to slice
	result := make([]*LanguageSummary, 0, len(byLang))
	for _, s := range byLang {
		result = append(result, s)
	}

	// Sort
	sortSummaries(result, opts.Sort)

	return result
}

func sortSummaries(summaries []*LanguageSummary, sortBy string) {
	sort.Slice(summaries, func(i, j int) bool {
		a, b := summaries[i], summaries[j]
		switch sortBy {
		case "name":
			return strings.ToLower(a.Name) < strings.ToLower(b.Name)
		case "lines":
			if a.Lines != b.Lines {
				return a.Lines > b.Lines
			}
			return strings.ToLower(a.Name) < strings.ToLower(b.Name)
		case "blanks":
			if a.Blank != b.Blank {
				return a.Blank > b.Blank
			}
			return strings.ToLower(a.Name) < strings.ToLower(b.Name)
		case "code":
			if a.Code != b.Code {
				return a.Code > b.Code
			}
			return strings.ToLower(a.Name) < strings.ToLower(b.Name)
		case "comments":
			if a.Comment != b.Comment {
				return a.Comment > b.Comment
			}
			return strings.ToLower(a.Name) < strings.ToLower(b.Name)
		case "complexity":
			if a.Complexity != b.Complexity {
				return a.Complexity > b.Complexity
			}
			return strings.ToLower(a.Name) < strings.ToLower(b.Name)
		default: // "files"
			if a.Count != b.Count {
				return a.Count > b.Count
			}
			return strings.ToLower(a.Name) < strings.ToLower(b.Name)
		}
	})
}

