func makeBorderStr(width int, opts *Options) string {
	if opts.CI {
		return strings.Repeat("-", width)
	}
	return strings.Repeat("─", width)
}

// formatTabular formats output as a table
// Normal mode: 79 chars wide
// Wide mode: 109 chars wide
//
// Normal column widths (format string portions):
//   Language: %-20s (left-padded to 20)
//   Files:    %5s + 7 spaces = 12 total
//   Lines:    %5s + 4 spaces = 9 total
//   Blanks:   %6s + 2 spaces = 8 total
//   Comments: %8s + 7 spaces = 15 total
//   Code:     %4s + 1 space = 5 total
//   Complexity: %10s = 10 total
//   Total: 79

func formatTabular(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	isWide := opts.Wide || opts.Format == "wide"
	showULOC := opts.TrackULOC && !opts.TrackDryness
	showDryness := opts.TrackDryness
	showCharacter := opts.TrackCharacter
	showPercent := opts.Percent

	// Define column format
	type colDef struct {
		header   string
		width    int    // total column width including trailing spaces
		dataFmt  string // format for data (without trailing spaces)
		dataPad  int    // trailing spaces after right-aligned data
	}

	var cols []colDef
	var langColWidth int
	var langTruncWidth int // display width for truncation

	if isWide {
		langColWidth = 38
		langTruncWidth = 22
		cols = []colDef{
			{"", langColWidth, "", 0}, // language col handled separately
			{"Files", 10, "%5s", 5},
			{"Lines", 9, "%7s", 2},
			{"Blanks", 9, "%6s", 3},
			{"Comments", 11, "%8s", 3},
			{"Code", 9, "%5s", 4},
			{"Complexity", 11, "%10s", 1},
			{"Complexity/Lines", 16, "%16s", 0},
		}
	} else {
		langColWidth = 20
		langTruncWidth = 15
		cols = []colDef{
			{"", langColWidth, "", 0},
			{"Files", 12, "%5s", 7},
			{"Lines", 9, "%5s", 4},
			{"Blanks", 8, "%6s", 2},
			{"Comments", 15, "%8s", 7},
			{"Code", 5, "%4s", 1},
			{"Complexity", 10, "%10s", 0},
		}
	}

	// Add ULOC/Dryness column if needed
	if showDryness {
		if isWide {
			cols = append(cols, colDef{"DRYness", 12, "%12s", 0})
		} else {
			cols = append(cols, colDef{"DRYness", 12, "%12s", 0})
		}
	} else if showULOC {
		if isWide {
			cols = append(cols, colDef{"ULOC", 9, "%9s", 0})
		} else {
			cols = append(cols, colDef{"ULOC", 9, "%9s", 0})
		}
	}

	// Compute total width
	totalWidth := langColWidth
	for _, c := range cols[1:] {
		totalWidth += c.width
	}

	border := makeBorderStr(totalWidth, opts)

	printBorder := func() {
		if !opts.NoHBorder {
			fmt.Fprintln(w, border)
		}
	}

	// Build header line
	buildHeader := func() string {
		var sb strings.Builder
		// Language column
		sb.WriteString(fillRight("Language", langColWidth))
		// Remaining columns
		for _, c := range cols[1:] {
			// Right-align header in data field, then add pad
			headerStr := fmt.Sprintf(c.dataFmt, c.header)
			// Hmm, this isn't right. Let me think about how headers align
			// Header is LEFT-aligned at start of column with trailing spaces
			// Actually: header word right-aligns to where data right-aligns
			// So: format as right-aligned in (c.width) total
			sb.WriteString(fmt.Sprintf("%-*s", c.width, rightAlignHeader(c.header, c.width-c.dataPad, c.dataPad)))
		}
		return sb.String()
	}

	_ = buildHeader

	// Actually I know the exact format strings from analysis:
	// Normal: '%-20s%5s       %5s    %6s  %8s       %4s %10s'
	// With extra cols for ULOC/Dryness

	buildRow := func(lang string, values []string) string {
		var sb strings.Builder
		// Language
		langFormatted := formatLanguageName(lang, langColWidth, langTruncWidth)
		sb.WriteString(langFormatted)
		// Values
		for i, c := range cols[1:] {
			val := ""
			if i < len(values) {
				val = values[i]
			}
			sb.WriteString(fmt.Sprintf(c.dataFmt, val))
			if c.dataPad > 0 {
				sb.WriteString(strings.Repeat(" ", c.dataPad))
			}
		}
		return sb.String()
	}

	// Build actual header row using the same format as data rows
	headerValues := make([]string, len(cols)-1)
	for i, c := range cols[1:] {
		headerValues[i] = c.header
	}
	headerLine := buildRow("Language", headerValues)

	printBorder()
	fmt.Fprintln(w, headerLine)
	printBorder()

	// Print each language row
	for _, s := range summaries {
		values := make([]string, len(cols)-1)
		for i, c := range cols[1:] {
			switch c.header {
			case "Files":
				values[i] = formatInt(s.Count)
			case "Lines":
				values[i] = formatInt(s.Lines)
			case "Blanks":
				values[i] = formatInt(s.Blank)
			case "Comments":
				values[i] = formatInt(s.Comment)
			case "Code":
				values[i] = formatInt(s.Code)
			case "Complexity":
				values[i] = formatInt(s.Complexity)
			case "Complexity/Lines":
				if s.Lines > 0 {
					values[i] = fmt.Sprintf("%.2f", float64(s.Complexity)/float64(s.Lines))
				} else {
					values[i] = "0.00"
				}
			case "ULOC":
				values[i] = formatInt(s.ULOC)
			case "DRYness":
				if s.Code > 0 && s.ULOC > 0 {
					values[i] = fmt.Sprintf("%.1f%%", float64(s.ULOC)/float64(s.Code)*100)
				} else {
					values[i] = ""
				}
			}
		}
		fmt.Fprintln(w, buildRow(s.Name, values))

		// Percent row
		if showPercent {
			printPercentRow(summaries, s, values, cols, langColWidth, opts, w)
		}

		// Character row
		if showCharacter && s.LineLength != nil {
			charValues := make([]string, len(values))
			charValues[0] = "" // Files
			charValues[1] = "" // Lines - but put max here?
			// put MaxLine at 2nd-to-last, MeanLine at last
			// Actually: 'MaxLine / MeanLine     32          12'
			// Position: same as last two numeric columns
			// From observed output: "MaxLine / MeanLine     32          12"
			// This has MaxLine right-aligned in the "Code" position
			// and MeanLine right-aligned in the "Complexity" position
			// But the label "MaxLine / MeanLine" is in the Language column
			for j := range charValues {
				charValues[j] = ""
			}
			if len(charValues) >= 6 {
				charValues[len(charValues)-2] = strconv.Itoa(s.LineLength.Max)
				charValues[len(charValues)-1] = strconv.Itoa(int(math.Round(s.LineLength.Mean)))
			}
			fmt.Fprintln(w, buildRow("MaxLine / MeanLine", charValues))
		}

		// ULOC sub-row (when tracking ULOC without dryness)
		if showULOC && s.ULOC > 0 {
			ulocValues := make([]string, len(values))
			for j := range ulocValues {
				ulocValues[j] = ""
			}
			// ULOC value in Lines column
			if len(ulocValues) >= 2 {
				ulocValues[1] = formatInt(s.ULOC)
			}
			fmt.Fprintln(w, buildRow("(ULOC)", ulocValues))
			printBorder()
		}
	}

	printBorder()

	// By-file output
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				values := make([]string, len(cols)-1)
				for i, c := range cols[1:] {
					switch c.header {
					case "Files":
						values[i] = ""
					case "Lines":
						values[i] = formatInt(f.Lines)
					case "Blanks":
						values[i] = formatInt(f.Blanks)
					case "Comments":
						values[i] = formatInt(f.Comments)
					case "Code":
						values[i] = formatInt(f.Code)
					case "Complexity":
						values[i] = formatInt(f.Complexity)
					case "Complexity/Lines":
						if f.Lines > 0 {
							values[i] = fmt.Sprintf("%.2f", float64(f.Complexity)/float64(f.Lines))
						} else {
							values[i] = "0.00"
						}
					}
				}
				fmt.Fprintln(w, buildRow(f.Filename, values))
			}
			printBorder()
		}
	}

	// Total row
	totalFiles := int64(0)
	totalLines := int64(0)
	totalBlanks := int64(0)
	totalComments := int64(0)
	totalCode := int64(0)
	totalComplexity := int64(0)
	totalULOC := int64(0)
	for _, s := range summaries {
		totalFiles += s.Count
		totalLines += s.Lines
		totalBlanks += s.Blank
		totalComments += s.Comment
		totalCode += s.Code
		totalComplexity += s.Complexity
		totalULOC += s.ULOC
	}

	totalValues := make([]string, len(cols)-1)
	for i, c := range cols[1:] {
		switch c.header {
		case "Files":
			totalValues[i] = formatInt(totalFiles)
		case "Lines":
			totalValues[i] = formatInt(totalLines)
		case "Blanks":
			totalValues[i] = formatInt(totalBlanks)
		case "Comments":
			totalValues[i] = formatInt(totalComments)
		case "Code":
			totalValues[i] = formatInt(totalCode)
		case "Complexity":
			totalValues[i] = formatInt(totalComplexity)
		case "Complexity/Lines":
			if totalLines > 0 {
				totalValues[i] = fmt.Sprintf("%.2f", float64(totalComplexity)/float64(totalLines))
			} else {
				totalValues[i] = "0.00"
			}
		case "ULOC":
			totalValues[i] = formatInt(totalULOC)
		case "DRYness":
			totalValues[i] = ""
		}
	}
	fmt.Fprintln(w, buildRow("Total", totalValues))
	printBorder()

	// ULOC summary
	if showULOC && !showDryness {
		ulocTotalValues := make([]string, len(totalValues))
		for j := range ulocTotalValues {
			ulocTotalValues[j] = ""
		}
		if len(ulocTotalValues) >= 2 {
			ulocTotalValues[1] = formatInt(totalULOC)
		}
		fmt.Fprintln(w, buildRow("Unique Lines of Code (ULOC)", ulocTotalValues))
		printBorder()
	}

	// Dryness summary
	if showDryness {
		ulocSumValues := make([]string, len(totalValues))
		for j := range ulocSumValues {
			ulocSumValues[j] = ""
		}
		if len(ulocSumValues) >= 2 {
			ulocSumValues[1] = formatInt(totalULOC)
		}
		fmt.Fprintln(w, buildRow("Unique Lines of Code (ULOC)", ulocSumValues))

		var totalDryness float64
		if totalCode > 0 && totalULOC > 0 {
			totalDryness = float64(totalULOC) / float64(totalCode)
		}
		drynessValues := make([]string, len(totalValues))
		for j := range drynessValues {
			drynessValues[j] = ""
		}
		if len(drynessValues) >= 2 {
			drynessValues[1] = fmt.Sprintf("%.2f", totalDryness)
		}
		fmt.Fprintln(w, buildRow("DRYness %", drynessValues))
		printBorder()
	}

	// COCOMO
	if !opts.NoCocomo {
		cocomo := CalcCocomo(totalCode, opts)
		currencySymbol := opts.CurrencySymbol
		if currencySymbol == "" {
			currencySymbol = "$"
		}
		if !opts.SlocCountFormat {
			fmt.Fprintf(w, "Estimated Cost to Develop (%s) %s%s\n",
				cocomo.ProjectType,
				currencySymbol,
				formatMoneyInt(cocomo.EstimatedCost))
			fmt.Fprintf(w, "Estimated Schedule Effort (%s) %.2f months\n",
				cocomo.ProjectType, cocomo.ScheduleMonths)
			fmt.Fprintf(w, "Estimated People Required (%s) %.2f\n",
				cocomo.ProjectType, cocomo.PeopleRequired)
		} else {
			salary := opts.AvgWage
			if salary == 0 {
				salary = 56286
			}
			overhead := opts.Overhead
			if overhead == 0 {
				overhead = 2.4
			}
			eaf := opts.EAF
			if eaf == 0 {
				eaf = 1.0
			}
			fmt.Fprintf(w, "Total Physical Source Lines of Code (SLOC)                     = %s\n", formatInt(totalCode))
			fmt.Fprintf(w, "Development Effort Estimate, Person-Years (Person-Months)      = %.2f (%.2f)\n",
				cocomo.Effort/12, cocomo.Effort)
			fmt.Fprintf(w, " (Basic COCOMO model, Person-Months = %.2f*(KSLOC**%.2f)*%.2f)\n",
				getCocomoA(opts), getCocomoB(opts), eaf)
			fmt.Fprintf(w, "Schedule Estimate, Years (Months)                              = %.2f (%.2f)\n",
				cocomo.ScheduleMonths/12, cocomo.ScheduleMonths)
			fmt.Fprintf(w, " (Basic COCOMO model, Months = %.2f*(person-months**%.2f))\n",
				getCocomoC(opts), getCocomoD(opts))
			fmt.Fprintf(w, "Estimated Average Number of Developers (Effort/Schedule)       = %.2f\n",
				cocomo.PeopleRequired)
			fmt.Fprintf(w, "Total Estimated Cost to Develop                                = %s%s\n",
				currencySymbol,
				formatMoneyInt(cocomo.EstimatedCost))
			fmt.Fprintf(w, " (average salary = %s%s/year, overhead = %.2f)\n",
				currencySymbol,
				formatMoneyComma(float64(salary)),
				overhead)
		}
		printBorder()
	}

	// Size
	if !opts.NoSize {
		// Print XKCD note if applicable
		note := getXKCDNote(opts.SizeUnit)
		if note != "" {
			fmt.Fprintln(w, note)
		}
		sizeStr := formatBytesStr(totalBytes, opts.SizeUnit)
		fmt.Fprintf(w, "Processed %d bytes, %s\n", totalBytes, sizeStr)
		printBorder()
	} else if isWide && !opts.NoSize {
		// Wide mode always shows border at end even with --no-size?
		// Actually no, only when size line is printed
	}
}

