import subprocess, tempfile, os

def get_complexity(code, suffix):
    with tempfile.NamedTemporaryFile(suffix=suffix, mode='w', delete=False) as f:
        f.write(code)
        fname = f.name
    result = subprocess.run(['./executable', fname], capture_output=True, text=True)
    compl = -1
    for line in result.stdout.split('\n'):
        words = line.split()
        if len(words) >= 7 and not line.startswith(('─','L','T','E','P')):
