                compl = int(words[-1])
                break
            except: pass
    os.unlink(fname)
    return compl

# Key question: does scc count "else" for Java?
code_java = '''public class T {
    void f() {
        if (x) {
        } else {
        }
    }
}'''
print('Java if+else:', get_complexity(code_java, '.java'))

