cat > /workspace/tabwriter.go << 'GOEOF'
package main

import (
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"
)

// tabularFormat writes the tabular output
// Normal format (79 chars):
//   Language(20L) Files(5R+7) Lines(5R+4) Blanks(6R+2) Comments(8R+7) Code(4R+1) Complexity(10R)
//   = "%-20s%5s       %5s    %6s  %8s       %4s %10s"
//
// Wide format (109 chars):
//   Language(38L) Files(5R) Lines(10R) Blanks(9R) Comments(10R) Code(9R) Complexity(11R) CL(17R)
//   = "%-38s%5s%10s%9s%10s%9s%11s%17s"

func writeTabular(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	isWide := opts.Wide || opts.Format == "wide"
	showULOC := opts.TrackULOC && !opts.TrackDryness
	showDryness := opts.TrackDryness
	showCharacter := opts.TrackCharacter
	showPercent := opts.Percent

	var (
		langColWidth  int
		langTruncAt   int
		totalWidth    int
		normalFmt     string
		extraColHdr   string
		extraColWidth int
	)

	if isWide {
		langColWidth = 38
		langTruncAt = 22
		totalWidth = 109
		normalFmt = "%-38s%5s%10s%9s%10s%9s%11s%17s"
		// wide format doesn't have extra columns by default
	} else {
		langColWidth = 20
		langTruncAt = 15
		totalWidth = 79
		normalFmt = "%-20s%5s       %5s    %6s  %8s       %4s %10s"
	}

	if showULOC && !showDryness {
		if isWide {
			extraColHdr = "ULOC"
			extraColWidth = 9
			normalFmt += "%9s"
			totalWidth += 9
		} else {
			extraColHdr = "ULOC"
			extraColWidth = 9
			normalFmt += "%9s"
			totalWidth += 9
		}
	} else if showDryness {
		if isWide {
			extraColHdr = "DRYness"
			extraColWidth = 12
			normalFmt += "%12s"
			totalWidth += 12
		} else {
			extraColHdr = "DRYness"
			extraColWidth = 12
			normalFmt += "%12s"
			totalWidth += 12
		}
	}

	_ = extraColWidth

	border := makeBorderStr(totalWidth, opts)

	printBorder := func() {
		if !opts.NoHBorder {
			fmt.Fprintln(w, border)
		}
	}

	// Format a row given a language name and data values
	// values order: Files, Lines, Blanks, Comments, Code, Complexity [, Complexity/Lines if wide] [, extra]
	buildRow := func(langName string, vals []string) string {
		langFormatted := formatLanguageName(langName, langColWidth, langTruncAt)
		if isWide {
			// Wide: 8 values (or 9 with extra)
			files := getVal(vals, 0)
			lines := getVal(vals, 1)
			blanks := getVal(vals, 2)
			comments := getVal(vals, 3)
			code := getVal(vals, 4)
			complexity := getVal(vals, 5)
			cpl := getVal(vals, 6)
			if extraColHdr != "" {
				extra := getVal(vals, 7)
				return fmt.Sprintf(normalFmt, langFormatted, files, lines, blanks, comments, code, complexity, cpl, extra)
			}
			return fmt.Sprintf(normalFmt, langFormatted, files, lines, blanks, comments, code, complexity, cpl)
		} else {
			// Normal: 7 values (or 8 with extra)
			files := getVal(vals, 0)
			lines := getVal(vals, 1)
			blanks := getVal(vals, 2)
			comments := getVal(vals, 3)
			code := getVal(vals, 4)
			complexity := getVal(vals, 5)
			if extraColHdr != "" {
				extra := getVal(vals, 6)
				return fmt.Sprintf(normalFmt, langFormatted, files, lines, blanks, comments, code, complexity, extra)
			}
			return fmt.Sprintf(normalFmt, langFormatted, files, lines, blanks, comments, code, complexity)
		}
	}

	// Header row
	var headerVals []string
	if isWide {
		headerVals = []string{"Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Complexity/Lines"}
	} else {
		headerVals = []string{"Files", "Lines", "Blanks", "Comments", "Code", "Complexity"}
	}
	if extraColHdr != "" {
		headerVals = append(headerVals, extraColHdr)
	}

	printBorder()
	fmt.Fprintln(w, buildRow("Language", headerVals))
	printBorder()

	// Print each language
	for _, s := range summaries {
		var cpl string
		if isWide {
			if s.Lines > 0 {
				cpl = fmt.Sprintf("%.2f", float64(s.Complexity)/float64(s.Lines))
			} else {
				cpl = "0.00"
			}
		}

		vals := makeLangVals(s, isWide, showULOC, showDryness, cpl)
		fmt.Fprintln(w, buildRow(s.Name, vals))

		// Percent row
		if showPercent {
			pctVals := makePercentVals(summaries, s, isWide, showULOC, showDryness)
			fmt.Fprintln(w, buildRow("Percentage", pctVals))
			// Print dashes separator
			dashLine := makeSeparator(totalWidth, opts)
			fmt.Fprintln(w, dashLine)
		}

		// Character row
		if showCharacter && s.LineLength != nil {
			charVals := makeEmptyVals(len(headerVals) - 1) // -1 because Files is empty
			// Put max/mean in specific positions
			if isWide {
				// Max in Code position (idx 4), Mean in Complexity position (idx 5)
				charVals[4] = strconv.Itoa(s.LineLength.Max)
				charVals[5] = strconv.Itoa(int(math.Round(s.LineLength.Mean)))
			} else {
				// Max in Code position (idx 4), Mean in Complexity position (idx 5)
				charVals[4] = strconv.Itoa(s.LineLength.Max)
				charVals[5] = strconv.Itoa(int(math.Round(s.LineLength.Mean)))
			}
			fmt.Fprintln(w, buildRow("MaxLine / MeanLine", charVals))
		}

		// ULOC sub-row
		if showULOC && s.ULOC > 0 {
			ulocVals := makeEmptyVals(len(headerVals) - 1)
			ulocVals[1] = formatInt(s.ULOC) // Lines position
			fmt.Fprintln(w, buildRow("(ULOC)", ulocVals))
			printBorder()
		}
	}

	printBorder()

	// By-file output
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				var cpl string
				if isWide {
					if f.Lines > 0 {
						cpl = fmt.Sprintf("%.2f", float64(f.Complexity)/float64(f.Lines))
					} else {
						cpl = "0.00"
					}
				}
				vals := makeFileVals(f, isWide, cpl)
				fmt.Fprintln(w, buildRow(f.Filename, vals))
			}
			printBorder()
		}
	}

	// Total row
	var totFiles, totLines, totBlanks, totComments, totCode, totComplexity, totULOC int64
	for _, s := range summaries {
		totFiles += s.Count
		totLines += s.Lines
		totBlanks += s.Blank
		totComments += s.Comment
		totCode += s.Code
		totComplexity += s.Complexity
		totULOC += s.ULOC
	}

	totLS := &LanguageSummary{
		Count:      totFiles,
		Lines:      totLines,
		Blank:      totBlanks,
		Comment:    totComments,
		Code:       totCode,
		Complexity: totComplexity,
		ULOC:       totULOC,
	}

	var totCpl string
	if isWide {
		if totLines > 0 {
			totCpl = fmt.Sprintf("%.2f", float64(totComplexity)/float64(totLines))
		} else {
			totCpl = "0.00"
		}
	}
	totalVals := makeLangVals(totLS, isWide, showULOC, showDryness, totCpl)
	fmt.Fprintln(w, buildRow("Total", totalVals))
	printBorder()

	// ULOC summary
	if showULOC && !showDryness {
		ulocTotalVals := makeEmptyVals(len(headerVals) - 1)
		ulocTotalVals[1] = formatInt(totULOC)
		fmt.Fprintln(w, buildRow("Unique Lines of Code (ULOC)", ulocTotalVals))
		printBorder()
	}

	// Dryness summary
	if showDryness {
		ulocTotalVals := makeEmptyVals(len(headerVals) - 1)
		ulocTotalVals[1] = formatInt(totULOC)
		fmt.Fprintln(w, buildRow("Unique Lines of Code (ULOC)", ulocTotalVals))

		var overallDry float64
		if totCode > 0 && totULOC > 0 {
			overallDry = float64(totULOC) / float64(totCode)
		}
		drynessVals := makeEmptyVals(len(headerVals) - 1)
		drynessVals[1] = fmt.Sprintf("%.2f", overallDry)
		fmt.Fprintln(w, buildRow("DRYness %", drynessVals))
		printBorder()
	}

	// COCOMO
	if !opts.NoCocomo {
		cocomo := CalcCocomo(totCode, opts)
		curr := opts.CurrencySymbol
		if curr == "" {
			curr = "$"
		}
		if !opts.SlocCountFormat {
			fmt.Fprintf(w, "Estimated Cost to Develop (%s) %s%s\n",
				cocomo.ProjectType, curr, formatMoneyInt(cocomo.EstimatedCost))
			fmt.Fprintf(w, "Estimated Schedule Effort (%s) %.2f months\n",
				cocomo.ProjectType, cocomo.ScheduleMonths)
			fmt.Fprintf(w, "Estimated People Required (%s) %.2f\n",
				cocomo.ProjectType, cocomo.PeopleRequired)
		} else {
			salary := opts.AvgWage
			if salary == 0 {
				salary = 56286
			}
			overhead := opts.Overhead
			if overhead == 0 {
				overhead = 2.4
			}
			eaf := opts.EAF
			if eaf == 0 {
				eaf = 1.0
			}
			fmt.Fprintf(w, "Total Physical Source Lines of Code (SLOC)                     = %s\n", formatInt(totCode))
			fmt.Fprintf(w, "Development Effort Estimate, Person-Years (Person-Months)      = %.2f (%.2f)\n",
				cocomo.Effort/12, cocomo.Effort)
			fmt.Fprintf(w, " (Basic COCOMO model, Person-Months = %.2f*(KSLOC**%.2f)*%.2f)\n",
				getCocomoA(opts), getCocomoB(opts), eaf)
			fmt.Fprintf(w, "Schedule Estimate, Years (Months)                              = %.2f (%.2f)\n",
				cocomo.ScheduleMonths/12, cocomo.ScheduleMonths)
			fmt.Fprintf(w, " (Basic COCOMO model, Months = %.2f*(person-months**%.2f))\n",
				getCocomoC(opts), getCocomoD(opts))
			fmt.Fprintf(w, "Estimated Average Number of Developers (Effort/Schedule)       = %.2f\n",
				cocomo.PeopleRequired)
			fmt.Fprintf(w, "Total Estimated Cost to Develop                                = %s%s\n",
				curr, formatMoneyInt(cocomo.EstimatedCost))
			fmt.Fprintf(w, " (average salary = %s%s/year, overhead = %.2f)\n",
				curr, formatMoneyComma(float64(salary)), overhead)
		}
		printBorder()
	}

	// Size
	if !opts.NoSize {
		note := getXKCDNote(opts.SizeUnit)
		if note != "" {
			fmt.Fprintln(w, note)
		}
		sizeStr := formatBytesStr(totalBytes, opts.SizeUnit)
		fmt.Fprintf(w, "Processed %d bytes, %s\n", totalBytes, sizeStr)
		printBorder()
	}
}

func getVal(vals []string, idx int) string {
	if idx < len(vals) {
		return vals[idx]
	}
	return ""
}

func makeEmptyVals(n int) []string {
	vals := make([]string, n)
	for i := range vals {
		vals[i] = ""
	}
	return vals
}

func makeLangVals(s *LanguageSummary, isWide bool, showULOC bool, showDryness bool, cpl string) []string {
	var vals []string
	if isWide {
		vals = []string{
			formatInt(s.Count),
			formatInt(s.Lines),
			formatInt(s.Blank),
			formatInt(s.Comment),
			formatInt(s.Code),
			formatInt(s.Complexity),
			cpl,
		}
	} else {
		vals = []string{
			formatInt(s.Count),
			formatInt(s.Lines),
			formatInt(s.Blank),
			formatInt(s.Comment),
			formatInt(s.Code),
			formatInt(s.Complexity),
		}
	}
	if showULOC && !showDryness {
		vals = append(vals, formatInt(s.ULOC))
	} else if showDryness {
		var dry string
		if s.Code > 0 && s.ULOC > 0 {
			dry = fmt.Sprintf("%.1f%%", float64(s.ULOC)/float64(s.Code)*100)
		}
		vals = append(vals, dry)
	}
	return vals
}

func makeFileVals(f *FileResult, isWide bool, cpl string) []string {
	if isWide {
		return []string{
			"",
			formatInt(f.Lines),
			formatInt(f.Blanks),
			formatInt(f.Comments),
			formatInt(f.Code),
			formatInt(f.Complexity),
			cpl,
		}
	}
	return []string{
		"",
		formatInt(f.Lines),
		formatInt(f.Blanks),
		formatInt(f.Comments),
		formatInt(f.Code),
		formatInt(f.Complexity),
	}
}

func makePercentVals(all []*LanguageSummary, s *LanguageSummary, isWide bool, showULOC bool, showDryness bool) []string {
	var totFiles, totLines, totBlanks, totComments, totCode, totComplexity int64
	for _, ls := range all {
		totFiles += ls.Count
		totLines += ls.Lines
		totBlanks += ls.Blank
		totComments += ls.Comment
		totCode += ls.Code
		totComplexity += ls.Complexity
	}

	pct := func(part, total int64) string {
		if total == 0 {
			return "NaN%"
		}
		return fmt.Sprintf("%.1f%%", float64(part)/float64(total)*100)
	}

	vals := []string{
		pct(s.Count, totFiles),
		pct(s.Lines, totLines),
		pct(s.Blank, totBlanks),
		pct(s.Comment, totComments),
		pct(s.Code, totCode),
		pct(s.Complexity, totComplexity),
	}
	if isWide {
		vals = append(vals, "") // Complexity/Lines %
	}
	if showULOC && !showDryness {
		vals = append(vals, "") // ULOC %
	} else if showDryness {
		vals = append(vals, "") // Dryness %
	}
	return vals
}

func makeSeparator(width int, opts *Options) string {
	if opts.CI {
		return strings.Repeat("-", width)
	}
	return strings.Repeat("-", width)
}

func writeWide(summaries []*LanguageSummary, opts *Options, totalBytes int64, elapsed float64, w io.Writer) {
	writeTabular(summaries, opts, totalBytes, elapsed, w)
}
GOEOF
