}

func makeLangVals(s *LanguageSummary, isWide bool, showULOC bool, showDryness bool, cpl string) []string {
	var vals []string
	if isWide {
		vals = []string{
			formatInt(s.Count),
			formatInt(s.Lines),
			formatInt(s.Blank),
			formatInt(s.Comment),
			formatInt(s.Code),
			formatInt(s.Complexity),
			cpl,
		}
	} else {
		vals = []string{
			formatInt(s.Count),
			formatInt(s.Lines),
			formatInt(s.Blank),
			formatInt(s.Comment),
			formatInt(s.Code),
			formatInt(s.Complexity),
		}
	}
	if showULOC && !showDryness {
		vals = append(vals, formatInt(s.ULOC))
