package main

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

// formatFilePath formats a file path for by-file output
// Normal mode: max 32 chars (lang+files combined), tail-truncate if > 26
// Wide mode: max 43 chars, tail-truncate if > 42
func formatFilePath(path string, isWide bool) string {
	if isWide {
		return formatFilePathWidth(path, 43, 42)
	}
	return formatFilePathWidth(path, 32, 26)
}

func formatFilePathWidth(path string, padWidth, maxDisplay int) string {
	// Calculate display width (all ASCII for file paths)
	dw := displayWidth(path)
	if dw <= maxDisplay {
		// No truncation needed, pad to padWidth
		return fillRightBytes(path, padWidth)
	}
	// Tail-truncate: keep last maxDisplay-1 runes, prepend '~'
	runes := []rune(path)
	keepCount := maxDisplay - 1 // keep last (maxDisplay-1) chars
	if keepCount < 0 {
		keepCount = 0
	}
	if keepCount > len(runes) {
		keepCount = len(runes)
	}
	tail := string(runes[len(runes)-keepCount:])
	result := "~" + tail
	return fillRightBytes(result, padWidth)
}

func displayWidth(s string) int {
	// For ASCII paths, display width = rune count
	// For Unicode paths, use runeWidth
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}

func fillRightBytes(s string, w int) string {
	sw := displayWidth(s)
	if sw >= w {
		return s
	}
	return s + strings.Repeat(" ", w-sw)
}

// buildByFileRow creates a by-file data row
// Places numbers at fixed absolute positions
