# Looking at the output for single language:
# Go: (ULOC)=25, Unique Lines=25 (same as per-language since only 1 language)
# For multi-language: total is 47 (global unique)

# I'll add GlobalULOC to the result struct or pass as a separate value

# Simplest approach: add a field to LanguageSummary that represents the global total
# OR: change the formatter to compute global ULOC differently

# Actually, the BEST approach: track global unique separately in AggregateResults

with open('/workspace/formatter.go', 'r') as f:
    content = f.read()

# Add GlobalULOC computation in AggregateResults
old_uloc = '''	// For ULOC, compute unique lines across all files per language
\tif opts.TrackULOC {
\t\tlangHashes := make(map[string]map[string]bool)
\t\tfor _, r := range results {
\t\t\tif r == nil || r.LineHashes == nil {
\t\t\t\tcontinue
\t\t\t}
\t\t\tif _, ok := langHashes[r.Language]; !ok {
\t\t\t\tlangHashes[r.Language] = make(map[string]bool)
\t\t\t}
\t\t\tfor k := range r.LineHashes {
\t\t\t\tlangHashes[r.Language][k] = true
\t\t\t}
\t\t}
\t\tfor lang, hashes := range langHashes {
\t\t\tif s, ok := byLang[lang]; ok {
\t\t\t\ts.ULOC = int64(len(hashes))
\t\t\t}
\t\t}
\t}'''

new_uloc = '''	// For ULOC, compute unique lines across all files per language and globally
\tvar globalULOC int64
\tif opts.TrackULOC {
\t\tlangHashes := make(map[string]map[string]bool)
\t\tglobalHashes := make(map[string]bool)
\t\tfor _, r := range results {
\t\t\tif r == nil || r.LineHashes == nil {
\t\t\t\tcontinue
\t\t\t}
\t\t\tif _, ok := langHashes[r.Language]; !ok {
\t\t\t\tlangHashes[r.Language] = make(map[string]bool)
\t\t\t}
\t\t\tfor k := range r.LineHashes {
\t\t\t\tlangHashes[r.Language][k] = true
\t\t\t\tglobalHashes[k] = true
\t\t\t}
