\t\t\t\tfmt.Fprintln(w, buildInfoRow("(ULOC)", formatInt(s.ULOC)))
\t\t\t}
\t\t\tprintBorder()
\t\t} else {
\t\t\t// ULOC sub-row (non by-file mode)
\t\t\tif showULOC && s.ULOC > 0 {
\t\t\t\tfmt.Fprintln(w, buildInfoRow("(ULOC)", formatInt(s.ULOC)))
\t\t\t\t// Add separator between language sections (when not last)
\t\t\t\tif !isLastLang {
\t\t\t\t\tsepLine := makeSeparator(totalWidth, opts)
\t\t\t\t\tfmt.Fprintln(w, sepLine)
\t\t\t\t}
\t\t\t}
\t\t}'''

content = content.replace(old_section, new_section, 1)

with open('/workspace/tabwriter.go', 'w') as f:
    f.write(content)
print("Restructured ULOC and by-file sections")
EOF

